INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_1_0','游柴桑怀渊明二绝','喻良能','宋','语客归休醉欲眠，
素琴虽蓄本无弦。
南窗寄傲北窗卧，
买断清风不用钱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_1','湖上二绝','喻良能','宋','初过百六见梨花，
堤路烟轻雨更斜。
玉雪一枝端可念，
柳丝深处水边家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_2','湖上二绝','喻良能','宋','轻阴疏雨帝城西，
目断裙腰绿正齐。
处处春风围绣幕，
行云莫与湿障泥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_3','湖口主簿刘君少魏以皂湖石二峰见遗其一盘拗呀豁彷佛金华洞天因目之曰小三洞赋诗一绝','喻良能','宋','片石来从凤枳家，
天然崖窾自唅呀。
从今喻子新三洞，
不减坡翁旧九华。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_4','琵琶亭','喻良能','宋','琵琶人去几经秋，
司马青衫亦故丘。
唯有当时亭下水，
无情依旧更东流。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_5','登寺后峰绝顶','喻良能','宋','杳杳扶筇上翠岑，
松风萧飒五云深。
不知直自登临处，
下至平川几百寻。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_6','登望海亭','喻良能','宋','谁将龙脊置新亭，
一饷登临耳目醒。
欲识海门山尽处，
烂银堆里数螺青。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_7','登清音堂','喻良能','宋','堂上横看江上洲，
洲边春浪拍天浮。
晴栏倚遍无多景，
浩荡时时没白鸥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_8','登清音堂','喻良能','宋','洲以檀槽旧得名，
风来草木自成声。
青衫司马令人恨，
只作浔阳送客行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_9','登清音堂','喻良能','宋','平生秀句诵随州，
今日身亲历胜游。
欲赋江山无好语，
强赓归鸟与孤舟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_10','登蒜岭','喻良能','宋','三年乌石山边路，
每恨南留未北归。
今复无端登蒜岭，
却寻乌石认亲闱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_11','策杖','喻良能','宋','田园依峻岭，
牵兴每须登。
却得台郎力，
扶持借赤藤。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_12','紫君林','喻良能','宋','此君仍佩紫，
直节自来孤。
欲倩文夫子，
招邀入画图。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_13','腊前二日见青梅桃花','喻良能','宋','泽国寒多春事迟，
南来地暖意都迷。
城阴雨过腊初近，
梅子青青桃满蹊。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_14','谢司路钤遗菊花塔','喻良能','宋','夫君遗我菊浮屠，
分得清香供读书。
突兀便高三数尺，
层层画影绿扶疏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_15','谢陈苏州送酒','喻良能','宋','宫庠寂寂雀罗门，
宁有贤人倒绿樽。
赖得苏州情义重，
肯令从事问寒温。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_16','谢监丞子长雪中四绝','喻良能','宋','国子先生老宦游，
十年学省一狐裘。
饥雷有意鸣蝉腹，
寒粟无端起玉楼。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_17','谢监丞子长雪中四绝','喻良能','宋','水花剪剪坠同云，
万里横陈似画坤。
不见银杯兼缟带，
知谁肯访席为门。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_18','谢监丞子长雪中四绝','喻良能','宋','江边钓雪翁荷笠，
道上行人马度桥。
说与儿童须爱惜，
莫贪琼屑撼长条。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_19','谢监丞子长雪中四绝','喻良能','宋','万玉妃来遣目迷，
缟裙练帨颤鸾篦。
令人却忆桐川路，
粉蕊垂垂照玉溪。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_20','赋竹','喻良能','宋','冥搜高出月，
幽思渺裁云。
拟遣穷愁去，
那能无此君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_21','道上口占','喻良能','宋','陇北麦苗初覆块，
舍南梅蕊已含须。
小春似有芳菲意，
凭仗何人为写图。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_22','鹅池','喻良能','宋','空馀青李与来禽，
宝墨知谁是赏音。
未若山阴羽衣客，
等閒犹识爱鹅心。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_23','鹅湖双松亭','喻良能','宋','白壁长廊数十间，
峨峨佩剑两苍官。
艳阳满目皆桃李，
晚节如公可岁寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_24','椿桂堂','喻良能','宋','昔时共说窦家椿，
今见清门五桂新。
我亦乡闾誇盛事，
比君家尚少三人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_25','简张子温运使','喻良能','宋','宗丞矻矻不离口，
右司时时说解颐。
岂独当今三昧手，
故应胜古四愁诗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_26','简张子温运使','喻良能','宋','少陵子厚妙炉锤，
力不能追心自期。
杯水平时犹不直，
试求印可老宗师。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_27','蓬莱阁','喻良能','宋','绝知蓬岛异尘寰，
弱水相望万里间。
争似卧龙云际阁，
不劳跨海即鳌山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_28','鉴湖','喻良能','宋','忆昔未曾游鉴水，
画图髣髴见非真。
年来饱泛同苕霅，
宁愧江湖旧散人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_29','锦园小春','喻良能','宋','细雨将春上晓枝，
东风吹绿到涟漪。
长沟绕槛多佳处，
小径穿花无尽时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_30','誓节马驿读龙溪诗','喻良能','宋','博山一穗爇沉薰，
寄傲胡床笑此身。
马队也知非讲肆，
聊从开府乞清新。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_31','题五泄瀑布四首','喻良能','宋','瀑雨霏霏湿翠岚，
来从天半许谁探。
凌空踏尽崚嶒石，
始到峰头第一潭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_32','题五泄瀑布四首','喻良能','宋','越绝徒闻万壑流，
他山未比此山幽。
谁云十地有热恼，
但觉三伏生凉秋。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_33','题五泄瀑布四首','喻良能','宋','香炉太白有佳句，
雁荡老坡题画图。
安得二仙居至此，
新诗想见唾成珠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_34','题五泄瀑布四首','喻良能','宋','玉龙千丈自夭矫，
飞雨十里长廉纤。
愚柳一见心眼爽，
未须界围观水帘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_35','题太白祠堂','喻良能','宋','倒披绮裘草裹巾，
酒醒玉山来映人。
明月沧江故无恙，
骑鲸何处狎龙鳞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_36','题太白祠堂','喻良能','宋','长安酒楼歌管新，
一曲乌栖泣鬼神。
狂客解龟同一醉，
人人知是谪仙人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_37','题太白祠堂','喻良能','宋','潮生采石波涛险，
秋入青山草木寒。
千古风流无处觅，
空吟亭北倚栏干。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_38','题开先寺飞桥次待制王公韵','喻良能','宋','漱玉亭边百尺桥，
游人平步玉虹腰。
凭栏下瞰清渊底，
秋水无尘浸碧霄。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_39','题石榴洞','喻良能','宋','当年鸡犬白云中，
屋角榴花带露浓。
洞口只今无处觅，
唯馀碧水绕青榕。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_40','题石榴洞','喻良能','宋','溪谷幽深可避秦，
桃源风物画难真。
思量却得蓝超力，
解遣人知洞里春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_41','题石榴洞','喻良能','宋','有客持柯石门道，
避人避世白云边。
相逢惊喜还相问，
应说经今八百年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_42','题亦好亭集句','喻良能','宋','从士力难任，
何其挂怀抱。
不及在家贫，
在家贫亦好。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_43','题齐山翠微亭','喻良能','宋','山深云气多，
拨云寻径入。
但觉襟袖寒，
不知浓翠湿。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_44','题吴先生祠','喻良能','宋','先生高义薄层穹，
解使池庭化泮宫。
应笑兰亭旧豪逸，
溪山千古寂寥中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_45','题灵源洞','喻良能','宋','细数峰峦到石门，
缓移屐齿步云根。
一樽浊酒林间坐，
古木苍萝日月昏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_46','题灵源洞','喻良能','宋','鬼凿神镵巧更纡，
直疑有路到华胥。
坐来浓翠沾衣冷，
恰似飞来秋意初。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_47','题谷帘泉','喻良能','宋','此水名传自昔贤，
味甘谁敢斗芳鲜。
一瓯雪乳初尝罢，
知是人间第一泉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_48','题徐子由菊坡图','喻良能','宋','葺坡种菊当糇粮，
想见西风百本黄。
安得一尊相对饮，
为公满意赋柴桑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_49','题徐子由菊坡图','喻良能','宋','先生万事不挂眼，
独向秋丛餐落英。
未省折腰营五斗，
悬知今日有渊明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_50','题挹仙亭','喻良能','宋','鹤驾鸾骖入杳冥，
望中遗迹照人清。
只今缥缈烟云里，
应有仙家犬吠声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_51','题钱清江','喻良能','宋','不受百钱馈，
从兹号钱清。
至今千载后，
犹得仰佳名。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_52','题智者双清堂','喻良能','宋','潦收池净见鱼行，
木落山空鸟语鸣。
更待夜深来徙倚，
要看霜月斗波清。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_53','题湖上月林','喻良能','宋','月林风物最湖山，
十里烟绡映雾鬟。
欲识丹青难貌处，
渚鸥汀鹭有无间。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_54','题煮泉亭','喻良能','宋','甘香曾饮谷帘前，
携茗仍来试煮泉。
更觉清风生两腋，
始知鸿渐是茶仙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_55','题蓝田松竹图','喻良能','宋','风姿凛凛千君子，
冠剑堂堂两大臣。
著我中间哦五字，
只应斯立是前身。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_56','凝香阁','喻良能','宋','渠渠夏屋翠阴稠，
沉水香浓瑞霭浮。
愧我无才吟五字，
未妨燕寝似苏州。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_57','凝霜阁','喻良能','宋','岿然飞阁榜凝霜，
雪散冰丸却暑方。
治郡风流无处觅，
只应栋宇是甘棠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_58','磬湖小山激水作小溪','喻良能','宋','平湖激水转山流，
石涧萦纡走碧虬。
料得丹青无貌处，
白蘋红蓼满汀州。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_59','磬湖即事','喻良能','宋','十亩烟波阔，
平开一画图。
已添无数景，
唤作小西湖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_60','磬湖偶成','喻良能','宋','只欠退之盘谷序，
已成摩诘辋川图。
暮年宁复须西子，
不用扁舟向五湖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_61','赠神童陈朴','喻良能','宋','陈郎七岁富三冬，
此去声名动九重。
好践退之童子序，
莫随刘晏颂东封。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_62','曝书','喻良能','宋','秋阳千里晒，
聊复曝吾书。
自笑年来事，
昏眸眩鲁鱼。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_63','一室','喻良能','宋','阴阳一室冷兢兢，
燕坐何曾病郁蒸。
只拟纶巾持羽扇，
未须赤脚踏层冰。
满盘碧玉初投箸，
一榻清风更曲肱。
扫地焚香凉到骨，
疏帘何处欲挥蝇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_64','九日亦好园小集','喻良能','宋','疏雨萧萧岩桂香，
西风驱冷作重阳。
池塘秋草还争绿，
篱落寒花未肯黄。
又是一年新度节，
何妨九客共飞觞。
园亭低小殽蔬陋，
不比龙山吟帽狂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_65','九日同尤司户舟行游梅山','喻良能','宋','令节逢重九，
相携鉴上游。
扁舟浮舴艋，
左手把蝤蛑。
红叶明青眼，
黄花重白头。
晚来风色好，
归棹得夷犹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_66','九日青阳道中呈张主簿','喻良能','宋','重阳时候在青阳，
野店山肴对举觞。
菊蕊半开簪鬓好，
橘包初破噀人香。
西风有意吹纱帽，
细雨无情湿锦障。
但得一樽相对饮，
不须更问是他乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_67','九日诸暨道中示兴之','喻良能','宋','客里逢重九，
萧萧落叶风。
略无花对菊，
但有鬓如蓬。
蕉卷新收绿，
枫旗半展红。
登临语宗武，
剩喜一樽同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_68','九日偕成均同官北山登高二首','喻良能','宋','轻霞朝日两微茫，
沙路骎骎十里强。
照水有情枫叶赤，
倚崖无数菊花黄。
兴酣争举凌云笔，
醉熟重浮滟海觞。
明日蝶愁人亦懒，
未须归去苦匆忙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_69','九月五日周少府卫秀才会饮吴波亭周有诗因次韵','喻良能','宋','碧水初微落，
黄花亦未簪。
三人千里客，
尊酒五年心。
我独年齐白，
君皆句似阴。
不妨铛脚坐，
聊作夜深吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_70','二月二日大雪','喻良能','宋','磬湖二月雪，
寒气故裴回。
面市连天合，
银花照眼开。
送穷穷不去，
招隐隐难来。
幸有曲生在，
何妨略耻罍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_71','二月五日夜梦何茂恭论诗','喻良能','宋','不见水曹久，
相思亦已勤。
梦中不识路，
樽酒细论文。
家食甘春荠，
官居采泮芹。
何时真会面，
风月与平分。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_72','入局言怀','喻良能','宋','学省清秋好，
无尘意趣长。
讲馀帘影静，
坐久䌽衣凉。
未有裨王族，
真成耗太仓。
顾惭麋鹿质，
亦许玷朝行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_73','八月十三夜仲季二弟弄月亭对饮','喻良能','宋','今宵端正月，
故故向湖山。
玉兔窥杯凸，
冰娥怪鬓斑。
诗情甪里逸，
酒胆夏黄悭。
兴罢度桥处，
天风松桂间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_74','八月十五日夜试院玩月呈叶判官徐教授蔡主簿','喻良能','宋','西风细逐桂枝生，
秋月圆从屋角明。
欢伯向人端有意，
素娥于客亦多情。
试吟飞鹊南枝句，
更听春蚕食叶声。
从此涂山添胜事，
四翁相遇四难并。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_75','八月十六夜月','喻良能','宋','一更山吐月，
万里湛虚明。
聊当中秋色，
堪欣此夜情。
西风金盏侧，
香雾玉簪横。
却忆青莲语，
寒鸦栖复惊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_76','八月十四日亦好亭迟月不至分韵得秋字','喻良能','宋','亦好登临似庾楼，
是中风月最宜秋。
素娥欲赴经年约，
行雨潜分一段愁。
聊复飞觞追胜赏，
何妨秉烛事清游。
明年此夕看明月，
千里相思楚水头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_77','十一月二日与陆明府陈广文黄使君吴都曹江广文同饮于闳中堂修年契也酒后耳热因得小诗呈似','喻良能','宋','菊色犹黄处，
梅花未发天。
三山千里客，
一笑六同年。
公等多朱绂，
予方乏坐毡。
清谈仍痛饮，
应作画图传。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_78','十一月十日同幕府诸公游郡圃叶抚属得梅花一枝马抚属有诗因次韵','喻良能','宋','横枝十月要清诗，
南国今年尔许迟。
梦绕故山千叠叠，
眼看新萼一枝枝。
欲知影瘦香微处，
未称天寒日暮时。
却忆玉溪当日树，
浅霜深雪总相宜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_79','十月二十三日携家游裴园','喻良能','宋','笋舆趁晓踏铜驼，
休暇仍逢景色和。
閒挈壶觞游翠霭，
尽呼儿女看沧波。
茫茫烟渚群鸥下，
隐隐晴虹短棹过。
最是小春奇绝处，
梅花破萼未全多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_80','三月二十六日工部宿直','喻良能','宋','邃宇近霄汉，
微风摇竹梢。
漏声通五夜，
钟韵自三茅。
衣裌偏宜睡，
杯单讵用庖。
夙兴那敢后，
鸡唱已嘐嘐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_81','三月二十四再到永祐陵','喻良能','宋','扁舟投晓出重城，
春浪初肥绿满汀。
竹里几声泥滑滑，
河边十里草青青。
人家艾叶惊飞燕，
水面杨花点翠萍。
渐近昭陵佳气集，
五云松柏喜重经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_82','三月六日宴李家园亭','喻良能','宋','林园过元巳，
流水绕芳丛。
略彴半寻影，
酴醾一扇风。
杯盘花气里，
枕簟鸟声中。
公子敬爱客，
月明樽未空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_83','三月六日湖上分韵得山字','喻良能','宋','剩涨三篙水，
宽围十里山。
垂杨飞舞里，
细雨有无间。
把酒从杯溢，
题诗任鬓斑。
青春仍暇日，
莫惜晚西还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_84','之官括苍道出涵碧因题四韵以继宾客刘公之后尘云','喻良能','宋','平生性僻耽山水，
不愿加封万户侯。
但得双鱼长到眼，
未须万壑更争流。
只今奇绝齐三洞，
自昔流传遍九州。
记得当年小盘礴，
坐令炎赫变清秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_85','之官桐川道中口占','喻良能','宋','登道重逢驿，
离家再及晨。
云轻山色晓，
寒浅鸟声春。
碧涧梅花老，
银杯竹叶新。
前途风日好，
持用悦慈亲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_86','山阴','喻良能','宋','绿发经行处，
重来两鬓丝。
共谁论旧事，
何处有新诗。
鉴水春妍蚤，
兰亭雪意迟。
邦人争指似，
寿母近期颐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_87','己酉中秋','喻良能','宋','磬湖秋半溢清波，
一岁月明今夕多。
剩办新诗娱老境，
满倾太白醉冰娥。
一天风露寒衣袂，
举室儿童杂笑歌。
不是钴潭奇绝处，
未妨丁夜更娑婆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_88','广信道中','喻良能','宋','昔日题诗处，
重来续胜游。
绿阴初入夏，
苍鬓几经秋。
细雨渡头市，
孤烟汀际舟。
溪山虽信美，
翻恨不淹留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_89','中秋示仲文弟','喻良能','宋','古来佳节是中秋，
今比重阳许燕游。
已觉冰轮无限好，
不须玉斧更重修。
三飞惊鹊纷无定，
一点閒云净不留。
况有阿连同䌽戏，
何妨呼酒互相酬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_90','中秋终日雾雨予还自都下宿分水岭夜漏约七八刻月出乌饭草荐山之东徘徊窗牖间欣然把酒对之因赋长句','喻良能','宋','乌饭山边白玉团，
瑞光千丈溢清寒。
斜穿逆旅茆茨室，
正照先生苜蓿盘。
聊向青天思太白，
却吟飞鹊忆曹瞒。
今宵不拟逢明月，
更向尊前仔细看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_91','中秋爱山玩月','喻良能','宋','年年秋半在长安，
今夕园林且尽欢。
一笑团栾人似月，
十分潋滟酒生澜。
遍簪丹桂香巾袂，
尽吸清辉澡肺肝。
饮罢月斜吟兴动，
挥毫风露一天寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_92','乏酒','刘敞','北宋','摇落偏悲客，
清寒易中人。
寂寥那自守，
淡泊亦殊真。
浮俗仍皆醉，
虚谈浪饮醇。
高歌傲燕市，
忽忆重千钧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_93','书大洞僧壁','喻良能','宋','招提閟林麓，
鱼鼓白云边。
地僻疑无路，
山深别有天。
幽花充佛供，
好鸟伴僧禅。
何日征鞭暇，
重来借榻眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_94','书堂','喻良能','宋','每忆书堂好，
重来又十年。
征途聊复尔，
风物故依然。
松竹千岩暮，
云烟九月天。
凭栏佳兴发，
欲进剡溪船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_95','予卧病数日意思殊昏昏中秋强起陪老人把酒对月不敢濡唇吻思去岁在当涂试院与诸公饮酒赋诗又一载矣因成长句','喻良能','宋','楚水涂山各一涯，
今年还是去年时。
古来明月皆如此，
我试停杯一问之。
丹桂飘香知有子，
飞乌绕树似无枝。
直须看到冰轮昃，
忍负姮娥隔岁期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_96','五舅处士惠访小园作诗为谢','喻良能','宋','五舅多道气，
相过茹杞苗。
意行随绿径，
情话竟清宵。
送酒飞花急，
撩人鸟语娇。
不堪分手处，
风雨晚潇潇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_97','六月二十二日夜省宿一首','喻良能','宋','省庐频宿直，
何异在承明。
地峻江声近，
风轻荷气清。
鬓毛真骑省，
诗思小阴铿。
记得山村日，
驰情向玉京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_98','六月晦日同楼少府由钱塘门至上竺遂游下中竺憩冷泉亭涂中记所历','喻良能','宋','联舆缓步踏葱苍，
十里荷香杂稻香。
庚暑此时无一点，
秋风明月洒长廊。
林间岩洞侵衣润，
水际亭台彻骨凉。
何处山泉落檐溜，
恍疑飞雨晓浪浪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_99','天申节望阙口号','喻良能','宋','日永凉生殿阁风，
需云宴衎庆流虹。
明良叶德千龄遇，
臣妾倾心万国同。
葵影缓随羲驭转，
榴花高映御袍红。
西踰葱岭东辽海，
长属尧封禹贡中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_100','廿五兄宣义见招偕诸弟赴新亭宴集即席有作','喻良能','宋','潇洒新亭好，
松长桂亦稠。
清秋集鸿雁，
暇日劝觥筹。
既远含香直，
何辞秉烛游。
主人情义重，
终宴不知休。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_101','闻交代将至喜而成篇','喻良能','宋','三年泮水冷无毡，
赢得萧萧雪满颠。
晚景不妨供䌽戏，
他乡安敢废诗篇。
剩将杯酒浇行色，
速赁双童担近编。
任是身归落雁后，
乡心先抵磬湖边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_102','文举仙尉以诗寄似兼惠新安纸乳洞茶次韵奉酬','喻良能','宋','闭户莺声老，
开缄鲤素新。
多惭青眼旧，
远寄白头人。
佳楮冰天茧，
芳荿雪洞春。
著书兼破睡，
勒谢敢辞频。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_103','月桂堂','喻良能','宋','月桂堂何有，
池清桂影横。
画图宁办此，
玉斧巧修成。
入夜境逾妙，
才秋风又生。
饶阳岩石下，
隐约欠分明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_104','月桥诗','喻良能','宋','天迥月逾晶，
地偏人亦静。
箫然寻丈桥，
寄此绿净境。
洗盏荐寒光，
掬泉弄清影。
尘远耳目醒，
令人发深省。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_105','长至忆天衣旧游寄王状元','喻良能','宋','去年连辔到朝阳，
红日初添一线长。
八俊偶同人已羡，
四难俱得计真良。
浇肠竹叶惊深碧，
插鬓梅花咤浅黄。
回首只今深似梦，
云山烟水正相望。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_106','东归见梅','喻良能','宋','老大无堪鬓似银，
虚名犹复玷簪绅。
久为碌碌趋朝士，
暂作栖栖去国人。
行李冲寒归故里，
江梅偷煖报新春。
万钟于我何加益，
三釜新来喜及亲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_107','东轩即事','喻良能','宋','啸傲东轩得此生，
平章物理忆渊明。
晴塘滟滟起萍浪，
夏木阴阴求友声。
聊欲庶几三不惑，
谁能复较四难并。
旋烧蟹眼烹鹰爪，
啜罢呼儿课二京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_108','印印诗','喻良能','宋','印印秀而好，
明眸冰雪肤。
逢人赏岐嶷，
问字识之无。
若有万金药，
真成千里驹。
空花今已矣，
晬日一长吁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_109','史丞相生辰','喻良能','宋','长才蚤立太平基，
奥学曾为帝者师。
谋叶不资同列断，
规存长许后人随。
金鱼玉带今谁似，
橘绿橙黄景最宜。
再拜祝公千万寿，
三江细酌入瑶卮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_110','史丞相生辰','喻良能','宋','姓名久已覆金瓯，
一品师臣德业优。
黼扆尚询黄发旧，
衮衣难伴赤松游。
松筠劲节高三事，
桃李浓阴遍九州。
萧叶杨门端可继，
只今衮衮富公侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_111','司户李岩詹和予庐山诗二十一篇作诗为谢','喻良能','宋','东野龙钟誇白首，
岩詹矍铄事清修。
胸中似有九云梦，
笔下倒倾三峡流。
和我七言清有味，
能令三伏凛生秋。
当年庐阜赏心处，
恨不携公九日游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_112','宁川','喻良能','宋','平生满耳说宣城，
入境云烟照眼明。
过雨偏浓千嶂碧，
未秋先冷数溪清。
细看菡萏波间色，
时听绵蛮竹里声。
不是多才谢公子，
江山犹解发吟情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_113','对厅口号','喻良能','宋','欢声喜气溢黄堂，
解愠风清化日长。
簪绂尽倾千里目，
冕旒遥祝万年觞。
韵敲碧玉檀栾嫩，
色斗红妆菡萏香。
共庆庞恩新浃洽，
圣君文母寿无疆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_114','对镜芙蓉二岭相望仅三十里高不知几百尺十步九折殆不啻蜀道之难也己卯孟秋沿檄过之仆夫告痡己亦罢极因成小诗','喻良能','宋','石镜宁堪对，
芙蓉不是花。
险中多虎迹，
平处少人家。
曲六蛇行迥，
攲危鸟道斜。
白云宜入望，
不怕乱山遮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_115','帅参宴客于蓬莱阁林参议有诗次韵呈府公','喻良能','宋','久以嘉谋赞迩英，
暂分东浙慰苍生。
閒携僚吏挥金盏，
更遣娉婷吹玉笙。
霖雨千岩垂欲作，
孤舟野水未妨横。
匪因衮绣归黄閤，
还念知章在四明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_116','平湖','喻良能','宋','平湖潋潋浸葱苍，
画出风烟十亩强。
蜜曲六从霜后熟，
玉芙蓉向露中芳。
新开石洞连松碧，
低结萸房映菊黄。
最爱堤边秦地柳，
一回春到一回长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_117','戊子除夕追和陈简斋除夜一首','喻良能','宋','世事年来已饱更，
百年今夕两分平。
窗间蜡炬偎人煖，
瓶里梅花照眼明。
瓦屋三间聊足喜，
鬓霜千丈总堪惊。
明朝同上西山望，
应有江湖春水生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_118','由之流溪回亭午苦热小憩牧马寺','喻良能','宋','长途畏日欲流金，
聊向招提觅快襟。
翠合苔痕人寂寂，
凉生柏影院深深。
苦无俗物败佳思，
况有寒泉醒客心。
一饷清风寄蕲竹，
又飞征盖指城阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_119','由安仁回宿大木寺','喻良能','宋','御史题诗处，
山深草木雄。
一番青烧雨，
十里锦帆风。
婆饼林间语，
山茶叶上红。
明朝入于越，
吟咏与谁同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_120','由当涂回宿齐山用杜牧之韵','喻良能','宋','一望云烟兴欲飞，
晴光聊复步熹微。
几年想像空怀古，
今日登临自送归。
寒菊有花宜靖节，
澄江如练忆玄晖。
夜深静坐清人骨，
岩影侵阶月满衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_121','由建宁回三山道中重阳','喻良能','宋','征鞍初自富沙还，
乱叶殷红点碧山。
客里黄花惊度节，
镜中白发巧摧颜。
三休磴道惟频叹，
一饭茆檐得暂閒。
为想成均新榜帖，
阿奴才力胜黄间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_122','由真隐至枕峰寺','喻良能','宋','野外初凉冷，
征衫亦未重。
檀栾溪上竹，
勃窣道边榕。
秋意撩人切，
岚光泼眼浓。
更寻天竺寺，
却忆此高峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_123','由真隐至枕峰寺','喻良能','宋','南国清秋杪，
长林翠霭重。
懒黄千顷稻，
深碧万株榕。
峡水风前急，
方山雨后浓。
征鞍何所憩，
萧寺枕孤峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_124','石井','喻良能','宋','山右最佳处，
有泉生石傍。
虚明秋后月，
清冷雪前霜。
鳗井真牛后，
龙湫可雁行。
濯缨仍漱齿，
政尔不能忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_125','立秋日迓宣谕中丞奉怀宋嗣宗','喻良能','宋','绣斧离朝右，
羸骖走道周。
侵星宵不寐，
曝日夕初休。
天地方炎暑，
山林漫早秋。
广文官舍静，
应念汗交流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_126','记六月二十日湖上所见','喻良能','宋','羽客相携六一泉，
炎歊立变晓凉天。
陈朝古桧参天瘦，
和靖孤坟傍竹偏。
却向苏堤剥新芡，
更寻萧寺听寒蝉。
长吟小醉归来晚，
足底清风似欲仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_127','记梦','喻良能','宋','小窗幽阁睡初匀，
梦到钧天侍紫宸。
盘号搯桃真异器，
果名黄枣岂常珍。
殊恩并浃鸰原弟，
美味初尝鹤发亲。
愿竭精忠图报称，
觉来肝胆已轮囷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_128','丞相大资叶公挽词','喻良能','宋','双溪钟地谶，
一相破天荒。
道至黄扉重，
勋由紫府昌。
堤成欢百辟，
台坼泣群方。
盛烈铭钟鼎，
千秋耿不忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_129','丞相大资叶公挽词','喻良能','宋','德望堂堂重，
威名凛凛寒。
三年衮衣粲，
四海寸心丹。
绿野悲裴度，
苍生忆谢安。
白头宾客在，
惭痛泪阑干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_130','丞相王公挽词','喻良能','宋','炎统中兴日，
淳熙翊赞功。
宪邦同吉甫，
待旦类周公。
一品恩荣重，
三朝礼貌隆。
欲知勋业盛，
请视鼎彝中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_131','丞相王公挽词','喻良能','宋','维岳钟英粹，
兴王有俊良。
文章周卫武，
书考郭汾阳。
调燮民庸茂，
弥缝主道昌。
中台一宵坼，
四海泪滂滂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_132','丞相王公挽词','喻良能','宋','畴昔翘材馆，
疏庸获屡游。
衮衣无傲色，
吐握有勤求。
辅弼十年久，
雍容片善收。
至今天下士，
语及泪交流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_133','买舟至九里松游三天竺','喻良能','宋','解维凌皱玉，
辍棹理孤筇。
游遍三天竺，
行穷九里松。
泉声依石细，
山色共秋浓。
佳处吾能识，
幽岩倚秀峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_134','亦好园江梅变红仲文季直二弟有诗因次韵','喻良能','宋','萧萧亦好耐寒枝，
天与风流一段奇。
刻玉不惟工傲雪，
施朱端欲妙凝脂。
佳人赪颊今才见，
公子酡颜顷未知。
便好作轩名顿有，
二难连璧赋清诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_135','亦好园即事','喻良能','宋','谁将春色到山家，
湖绿平堤草满沙。
细刻真酥水仙蕊，
匀搓绛蜡海红花。
芳林得日莺还啭，
香径无风蝶自斜。
聊与后生修故事，
未妨诗酒作生涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_136','亦好园春晚再用前韵','喻良能','宋','境净山明别一家，
几多垂柳袅平沙。
閒中牵梦一池草，
空里愁人万点花。
细雨朝朝兼暮暮，
淡烟整整复斜斜。
绿阴青子真堪画，
满意春风磬水涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_137','亦好园海棠秋开红英满树','喻良能','宋','微云澹日映寒流，
画出西园一幅秋。
白帝幻成红玉蕊，
金风吹绽碧枝头。
睡馀艳艳真妃子，
梦罢愔愔一解愁。
熟赏细看须著句，
为君重赋紫绵揉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_138','亦好园梅花','喻良能','宋','一别经年见未曾，
冲寒相值意凌兢。
肌肤姑射仙人雪，
品格中山孺子冰。
清浅池塘春未动，
黄昏篱落月初棱。
从来自倚心如铁，
被恼如今似少陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_139','再用前韵','喻良能','宋','晚驱羸马背重城，
晓度层峦淡月明。
醉与别愁相唤醒，
秋兼诗思一齐清。
舞风繁蓼堤边影，
泣露寒蛩草际声。
欲驻征鞍聊小憩，
敢将王事徇私情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_140','再用前韵呈参议李郎中','喻良能','宋','独冷官曹有底忙，
经旬不得造门墙。
雨添垂柳丝丝碧，
风搅飞花片片香。
顾我摧颓如病颡，
羡公腾踏胜飞黄。
新诗迥出南丰右，
不是无香似海棠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_141','再用彝公长老韵赠嗣宗教授','喻良能','宋','居易青衫旧，
安仁素发新。
愁思中酒圣，
贫忍论钱神。
白也诗谁敌，
潮乎笔更亲。
生辰宿南斗，
同是数奇人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_142','同德坊寓居','喻良能','宋','天地方摇落，
江湖入梦思。
三为京辇客，
十见岁华移。
亹亹金闺直，
萧萧素发垂。
残年饱吃饭，
细诵少陵诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_143','安抚大资李参政生辰','喻良能','宋','仙李盘根几百秋，
我公勋业比伊周。
推恩已解宏元化，
戢患犹能庇七州。
不日定为黄閤老，
他年应伴赤松游。
三江愿得浑为酒，
寿斝年年给献酬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_144','安抚大资李参政生辰','喻良能','宋','崧岳生申占腊前，
预将和气作春妍。
蟠桃结实三千岁，
莲叶成巢几百年。
聊向蓬莱开燕寝，
即纡衮绣画凌烟。
只应便是神仙事，
方丈瀛洲却未然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_145','州宅','喻良能','宋','古栝提封接日畿，
专城皓首有光辉。
全家饱煖君恩重，
属邑丰登公事稀。
一簇楼台居洞府，
四时风景对屏帏。
多惭郎省无裨补，
丐外犹能占翠微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_146','戏䌽堂有作','喻良能','宋','捧檄及偏亲，
斑衣聊效颦。
旨甘贫有味，
温凊静无尘。
北户足萱草，
南风宜棘薪。
版舆多喜色，
庶不愧安仁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_147','有感二首','喻良能','宋','再有淮南乱，
纷纷几战场。
血腥官道雨，
骨映野田霜。
行阵青黄气，
朝廷赤白囊。
何时洗兵甲，
四海重耕桑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_148','有感二首','喻良能','宋','冉冉新华发，
飕飕敝黑裘。
一官方半剌，
六十已平头。
稠叠耶溪泛，
崎岖禹穴游。
未能江海去，
聊作稻粱谋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_149','次马抚干韵赠黄泰之状元','喻良能','宋','袖然射策向明光，
紫禁春深日正长。
风细御炉烟冉冉，
天晴宫柳絮茫茫。
玉阶亲奉唐虞问，
䌽笔浓薰班马香。
千佛经中名第一，
鸿文端不数长杨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_150','次陆务观韵题姚复之秀才适斋','喻良能','宋','姚子神情处处便，
床头周易杖头钱。
逢僧与语閒终日，
遣客归休醉欲眠。
应觉此生如寄耳，
何妨一室且萧然。
无心更觅封侯事，
纳履谁能博一编。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_151','次韵卫知机秀才梅花','喻良能','宋','东君调护亦多情，
瘦比夷齐彻骨清。
有韵绿毛时倒挂，
无尘白鹭可同盟。
未应桃叶能称姊，
若齿山樊定是兄。
何事故园频入梦，
疏枝新赏玉溪晴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_152','次韵马叔度再用前韵见寄','喻良能','宋','善弈从来数弈秋，
胜游今作子长游。
才多已觉悬河似，
诗妙无劳入海求。
画月裁云宁底巧，
奔泉抉石一何遒。
谁知倾盖成胶漆，
笑杀如新到白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_153','次韵木蕴之状元义乌道中一首','喻良能','宋','奔走尘埃老未休，
每思上下两岩稠。
关心簿领三书考，
回首家山两换秋。
支腹自怜鹪鼹小，
江湖谁计雁凫留。
又遮西日长安去，
惭愧平生马少游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_154','次韵木蕴之状元见寄之作','喻良能','宋','水绕星山木绕庐，
江城孤绝政愁予。
鸟言为吏居篁竹，
乌鬼得鱼欢里闾。
照眼梅花寒皎皎，
关心烟雨晚疏疏。
真山多谢遥相忆，
长句新诗细字书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_155','次韵王龟龄春日湖上','喻良能','宋','春老花茵积，
云开天镜磨。
暖风今日好，
细雨向来多。
柳荫青丝障，
湖明金叵罗。
何时成醉倒，
烟草藉晴坡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_156','次韵王龟龄谒大禹祠酌菲饮泉','喻良能','宋','不到稽山已十年，
梦中物色故依然。
忆寻绝境经幽寺，
曾向东风酌妙泉。
书穴雨馀云扑地，
鉴湖春昼水连天。
别来乔木高多少，
想见娇莺自在迁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_157','次韵王侍御夜宿高牙','喻良能','宋','相别三时久，
相望万里赊。
携书期过雁，
徙倚至昏鸦。
风雨番君国，
云烟夔子家。
何时趣归觐，
重许拜高牙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_158','次韵王侍御题诗史堂','喻良能','宋','欲识当年泣鬼神，
诗皆绢妇与齑辛。
洗空千古无凡马，
称到于今有几人。
肯与齐梁充后乘，
只应苏李是前身。
丰碑更著最佳处，
传示宜过一万春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_159','次韵王宫教见贻之什','喻良能','宋','家住涛江东复东，
渺然云浪接晴空。
半生仕路崎岖里，
十亩家山杳霭中。
来往未成三径乐，
笑谈还喜一樽同。
强将俚语赓妍倡，
曹郐端惭齿卫风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_160','次韵王待制刘侍郎倡和','喻良能','宋','衮衣犹未趣东归，
吴会先传蜀道诗。
急峡高江追子美，
清风明月笑严维。
花围白帝行春日，
香蔼黄堂坐啸时。
顾我迂疏堪底用，
强颜薪粟效支离。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_161','次韵叶省干重九楼上言怀','喻良能','宋','水落鱼龙已退藏，
小楼萧爽裌衣凉。
山云雨过无穷态，
岩桂风来不断香。
已分文章成白豕，
拟将富贵等黄粱。
嵇康潦倒浑无取，
岂复眉开一点黄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_162','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
红尘半点无。
自应成小隐，
谁复叹将芜。
香秫五十亩，
黄柑二百株。
何必随俯仰，
归去亦良图。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_163','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
林塘十亩宽。
露深花脸湿，
春浅柳眉攒。
只拟希高隐，
那能缚小官。
寿山谁问讯，
太白正虬蟠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_164','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
投閒日日来。
花时长夜饮，
雪后煖寒杯。
一径松篁影，
满畦桑柘栽。
未能湖海去，
幽兴亦悠哉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_165','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
萧斋竹径通。
疏帘捲雌霓，
曲槛倚雄风。
爱酒杜陵老，
煎茶桑苧翁。
菟裘真得计，
踪迹免飘蓬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_166','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
都无尘世喧。
穗禾临芰沼，
绳草对苔垣。
去就随佳酝，
穷通付寓言。
还同李长吉，
来过有高轩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_167','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
年年草色新。
醉眠攲柳幄，
吟坐俯苔茵。
栗里风烟古，
樊川花木春。
谁云无伴侣，
对影共三人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_168','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
芳篱占一涯。
自耘三径草，
不断四时花。
柳絮风中雪，
芙蓉水上霞。
银潢何处是，
不拟问仙槎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_169','次韵外舅黄虞卿为爱山园好八首','喻良能','宋','为爱山园好，
芒鞋步步高。
绿针挦露韭，
碧箸剪春蒿。
但得林泉趣，
谁能州县劳。
何惭王孝伯，
痛饮读离骚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_170','次韵刘淳叟见寄二首','喻良能','宋','出处双青鬓，
生涯一钓舟。
浅深山远近，
浓淡树稀稠。
隐几昼逾静，
捲帘春更幽。
何当乘兴去，
舣棹向汀洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_171','次韵刘淳叟见寄二首','喻良能','宋','九万垂云翼，
胡为乃倦飞。
丘园聊偃息，
岩阜故因依。
蝶栩新酣睡，
鸥驯久息机。
祇应与风景，
相赏莫相违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_172','次韵宇文舍人见贻之作','喻良能','宋','不见褚公今二年，
重来青眼尚依然。
偃松篇美天犹和，
正殿班清人孰先。
今日赤墀烦暂立，
他年黄阁径须迁。
白头宾客无聊甚，
只待吹嘘送上天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_173','次韵戏䌽老人重阳怀故园作','喻良能','宋','潇洒秋容雨后天，
丹青端似倩龙眠。
故园绿竹应今日，
异县黄花又一年。
微禄祇堪供菽水，
菲材安敢拟渊骞。
日来王事欣多暇，
聊向樽前一粲然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_174','次韵伯寿兄中秋玩月','喻良能','宋','中秋自古月华好，
何况浮云扫碧天。
不比寻常三五夕，
须知潋滟十分圆。
画檐影转犹宜饮，
银汉辉斜未忍眠。
却忆年时今夜里，
独将醒眼对婵娟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_175','次韵伯寿兄见寄','喻良能','宋','江国疏梅吐玉英，
故园想见木欣荣。
二年鸿雁碧云阔，
千里江湖春水生。
冉冉池塘应入梦，
潇潇风雨若为情。
行看戏䌽青萱发，
准拟芳樽相对倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_176','次韵伯寿兄秋日偶题','喻良能','宋','渐老良多感，
悲秋强自宽。
鬓惊潘掾白，
衣怯范生寒。
径合荒苔碧，
窗明落叶丹。
浇愁须暂醉，
忍放酒杯乾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_177','次韵伯寿兄宿华藏有感','喻良能','宋','水净溪空峰更青，
目虽未到已先明。
栋浮万缕晴云细，
轩拥千重夏木清。
幽兴入门应自适，
残樽下马与谁倾。
老僧斋罢唯须睡，
不信人间有月评。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_178','次韵何茂恭永新见寄之什','喻良能','宋','起家从吏役，
宁为食无鱼。
游乐废山泽，
怀归畏简书。
文章簿领外，
风采折腰馀。
卧辙从兹始，
为谋未觉疏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_179','次韵何茂恭重阳前二日见过','喻良能','宋','西风篱落兴悠然，
秋影横江雁贴天。
短发未成吹帽饮，
高吟先赠把茱篇。
黄花一笑小重九，
青眼相看又四年。
欲试烟波钓竿手，
南湖同上月明船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_180','次韵宋嗣宗梅花','喻良能','宋','野外江头一树垂，
正当霜后腊前时。
清如弘景松临阁，
韵似渊明菊映篱。
铁石广平曾作赋，
风流水部亦哦诗。
却愁折向妆台下，
莫遣佳人取次知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_181','次韵宋嗣宗梅花','喻良能','宋','洗尽红妆见玉颜，
一年相别此时看。
房陵粉水休争白，
姑射冰肌巧耐寒。
自爱一枝横竹外，
未须千树绕江干。
东风也是相欺得，
已作和羹一点酸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_182','次韵张持荷桂花','喻良能','宋','别驾风流继竹林，
名园幽榭水云深。
匀铺叶底森森碧，
细糁枝头粟粟金。
酒酌香浮杯面蚁，
诗成霜洒月中砧。
清芬冉冉仍多韵，
不比晴窗一穗沉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_183','次韵李大著春日杂诗十首','喻良能','宋','二载违枌社，
全家客帝都。
浊醪充上顿，
清俸付中厨。
亲老唯须养，
皇恩讵敢孤。
逍遥处山泽，
未忍学仙臞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_184','次韵李大著春日杂诗十首','喻良能','宋','素发已垂领，
故园犹未归。
鸟声思磴道，
柳色忆荆扉。
嫩绿枝边暗，
残红叶底稀。
几多新乳燕，
一一出巢飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_185','次韵李大著春日杂诗十首','喻良能','宋','屯云初解驳，
晓日有晶辉。
城郭红尘软，
江湖春水肥。
小舟浮绿净，
芳径步熹微。
起我故山思，
多惭未拂衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_186','次韵李大著春日杂诗十首','喻良能','宋','帝里春仍好，
风和昼漏迟。
但怀三釜乐，
遑恤北山移。
老大谙斑戏，
空疏愧色丝。
平生杜陵老，
耿耿寸心知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_187','次韵李大著春日杂诗十首','喻良能','宋','借居仍种菊，
往往似天随。
日味三春酒，
灯明午夜棋。
閒临永和帖，
细诵建安诗。
潦倒同中散，
欢欣似启期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_188','次韵李大著春日杂诗十首','喻良能','宋','花日浅明牖，
竹风低度墙。
举头空弱絮，
转盼堕危芳。
兴遣凭毛颖，
愁消赖羽觞。
阴阴繁夏木，
故里耿难忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_189','次韵李大著春日杂诗十首','喻良能','宋','偏亲须寸禄，
匠院敢辞留。
颇愧花经眼，
还应草唤愁。
身唯亲布被，
交已绝牙筹。
诗兴抽毫足，
无劳入海求。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_190','次韵李大著春日杂诗十首','喻良能','宋','贱子知何幸，
莱衣老更斑。
白头居杜曲，
清梦到香山。
琢句愁雕肾，
衔杯喜渥颜。
此身惭暮翼，
飞倦未知还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_191','次韵李大著春日杂诗十首','喻良能','宋','漫仕叹迟暮，
卜居城北偏。
已教山白石，
祇欠沼清泉。
帘透一檐月，
窗横数尺天。
杂花还映竹，
故故自芳妍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_192','次韵李大著春日杂诗十首','喻良能','宋','春晚饶芳景，
官閒得细看。
隔窗黄鸟并，
开卷壁鱼乾。
过雨苍苔湿，
迎风翠竹寒。
发华搔更短，
斗酒自相宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_193','次韵陈鲁望郎中','喻良能','宋','笔底词华盛，
宁论大小山。
敷腴建安际，
古澹贞元间。
未许窥三昧，
时容见一斑。
草堂诗律在，
风味唤仍还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_194','次韵侍御晚宿三叉口','喻良能','宋','故里频怀梓，
新堤未筑沙。
文章真吏部，
吟咏许刘叉。
酒盏孤风物，
诗筒隔岁华。
相思江路远，
烟雨茁芳葭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_195','次韵周希稷咏芭蕉','喻良能','宋','经年不接故人书，
开户逢渠了不殊。
谁运七轮风里扇，
时跳千斛雨中珠。
退之有意吟山石，
摩诘无心作画图。
为爱青青无俗韵，
故教移植傍庭隅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_196','次韵和夷仲节推陪府公游北山','喻良能','宋','红莲犹得爱青山，
翠木苍萝处处攀。
云水窟中聊假日，
簿书丛里暂偷閒。
幨帷车乘春同到，
灯火城门夜未关。
我亦林泉曾俯仰，
只今双屦又尘寰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_197','次韵和宗郎中中秋不饮','喻良能','宋','暮烟收尽玉盘生，
是处同欣此夜晴。
云断三山凝紫翠，
星稀万里湛虚明。
低临朱箔千寻白，
高并银潢一派清。
赖有䌽衣堪醉舞，
残樽深夜更重倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_198','次韵奉酬王给事见贻之什','喻良能','宋','谁知州宅似精庐，
山绕檐楹水绕除。
堂静惠风长细细，
楼高烟雨又疏疏。
贫如坡老工餐菊，
性似边韶懒读书。
赖有嵩山王给事，
作诗贻赠问何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_199','次韵奉酬参议林郎中见贻之作','喻良能','宋','紫宸畴昔幸同朝，
去国俄惊数舍遥。
轻细难沾时服赐，
氤氲正想御香飘。
年加赖有斑衣戏，
心静真同桂隐招。
龙瑞此时探禹穴，
天津何日渡京桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_200','次韵奉酬林明府咏梅','喻良能','宋','政足廉平诗更佳，
铁肠还解赋梅花。
律传和靖未多叶，
名接水曹今几家。
丹粉讵须烦巧妙，
清新止为写横斜。
拟携卷轴江东去，
乞与诗仙作意誇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_201','次韵奉酬茂恭送茉莉重台白莲','喻良能','宋','异暑歊然金欲流，
缟裙练帨两宜秋。
笑他山谷誇黄钿，
欲学令狐赋白楼。
粉笔有心争试巧，
红妆无面可障羞。
明来自足映茆屋，
况有诗轻万户侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_202','次韵奉酬黄泰之状元见寄','喻良能','宋','千佛经中第一人，
明光前殿奏雄文。
论心讵止称三益，
识面端能胜百闻。
畴昔清谈如扣玉，
只今佳句欲凌云。
高情已出苏州右，
未用清香扫地焚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_203','次韵季直小疾初愈见寄','喻良能','宋','暌违才一日，
怀想似三秋。
忽得五字句，
真成百不忧。
荷花要同赋，
竹径拟清游。
明夜月华满，
杖藜能过不。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_204','次韵季直弟春日雪','喻良能','宋','休惊双鬓二毛加，
且喜东君发物华。
未向林梢开嫩叶，
先于檐际舞飞花。
鼠须正好书春帖，
蟹眼偏宜试露芽。
便欲扁舟访安道，
不堪山驿水程赊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_205','次韵季野弟蜡梅','喻良能','宋','媚色全胜柳，
孤标半似梅。
蕊寒金粉腻，
香重麝脐开。
徐笔那能画，
并刀未易裁。
扶头中酒味，
安得一枝来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_206','次韵林参议七月七日见示新作','喻良能','宋','晓雨初过溽暑收，
微云澹月作新秋。
清风政对三休阁，
绝景还思八咏楼。
缑岭当年乘白鹤，
银河此夕渡痴牛。
寿觞一举烘堂乐，
净洗胸中万斛愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_207','次韵林参议小雪快晴','喻良能','宋','著地晶莹月在沙，
忍寒聊作短歌誇。
煖肌未办裁驼褐，
露趾唯应有革靴。
细点竹梢添爽洒，
偶经梅蕊映横斜。
何当既积还消后，
剩取清泠试叶嘉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_208','次韵林致甫参议西园宴集','喻良能','宋','西园潇洒似蓬丘，
容我追随飞盖游。
一一娉婷供笑语，
双双鸂鶒对沈浮。
嵁岩窈窕如天造，
洞壑清泠与目谋。
欲识清欢兼卜夜，
东山月色足淹留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_209','次韵茂恭元日大雪','喻良能','宋','逗晓褰帏著䌽衣，
忽惊庭户有光辉。
缓将柏叶随觞举，
细看梅花伴雪飞。
阿堵无心来润屋，
诗仙有句到柴扉。
酒酣笑共儿曹说，
去岁如今归未归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_210','次韵范伯廉机宜病起见寄','喻良能','宋','夫君自是颖囊锥，
何事翻为沧海遗。
造化小儿聊戏剧，
山林大药岂无资。
得閒因病还应乐，
信手挥毫却有诗。
休叹银杯成羽化，
会须拔剑拨年衰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_211','次韵俞尉春日遣兴','喻良能','宋','渐欣长昼煖，
欲解短炉围。
春色已如此，
故园犹未归。
韦编今日事，
回首去年非。
镜里衰迟色，
多惭壮志违。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_212','次韵赵禹平春日书怀','喻良能','宋','草色青青二月时，
物华虽是我庐非。
日明院宇燕相语，
花发园林莺乱飞。
无数小桃初掩映，
几多垂柳自因依。
春风十里归吟笔，
未用罗帏绣幕围。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_213','次韵赵景明呈许明府','喻良能','宋','卜昼开英集，
瑶林映珷玞。
顾惭梅隐吏，
缪接范莱芜。
官柳春犹浅，
江梅韵亦孤。
他年想风味，
应有汭川图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_214','次韵送季直弟入越','喻良能','宋','积雨新晴耳目醒，
长阶柳色静閒庭。
已看桃萼胭脂湿，
未有杨花雪片零。
客路汝应怀稚子，
家居吾亦念樵青。
须知两地无百里，
不用阳关肠断听。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_215','次韵程观过夜饮灵济祠下','喻良能','宋','松月泻清影，
炉烟凝宿云。
檠灯寒照席，
樽酒细论文。
清漏转三鼓，
芳杯釂十分。
纷胜银烛里，
妙舞看榴裙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_216','次韵谢子良咏雪','喻良能','宋','晚来寒气重，
景物故撩人。
不厌诗雕肾，
宁辞酒入唇。
恍惊残夜月，
疑梦故园春。
欲倩何人画，
纷纷飞玉尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_217','次韵谢察院田寺丞倡酬之作','喻良能','宋','两翁辞采偶同时，
春草还应梦谢池。
出月穿天端有意，
掀雷抉电岂无期。
推门不作孤吟苦，
击钵犹嫌得句迟。
顾我无才难入社，
焚香时许诵清诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_218','自题木假山','喻良能','宋','根干轮囷蔽马牛，
何年飘泊寄沧洲。
幽岩邃壑渔罾得，
百巧千奇云浪锼。
好唤老泉来作记，
肯将居士与同游。
毕宏韦偃丹青妙，
画得天然意绪不。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_219','至日见梅','喻良能','宋','渐老身仍健，
多愁鬓易华。
异乡逢至节，
细雨见梅花。
酒薄那能醉，
诗成敢自誇。
何时故园里，
徙倚看横斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_220','西禅寺','喻良能','宋','脩廊千柱压城阴，
山并庐山胜二林。
六月檐楹无暑气，
四时山水有清音。
鸟飞不尽上方远，
鲸吼希闻别院深。
更欲题诗发佳境，
泮林讲说总关心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_221','访何茂恭于南湖何有诗因次韵','喻良能','宋','相别三年久，
相逢一笑时。
眼边无俗物，
袖里有清诗。
山路梅花早，
湖天雪意迟。
不眠成夜话，
寒月在疏枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_222','过东亭湖','喻良能','宋','篮舆诘旦过东亭，
日出烟销十里平。
翠袖舞风菰叶举，
红妆照水藕花生。
恨无钓艇浮深碧，
赖有吟毫赋晓晴。
归对老人誇胜赏，
从今不数鉴湖清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_223','过严濑寄陆守务观','喻良能','宋','翰墨场中老伏波，
挥毫快马下晴坡。
三年睿主思献纳，
千里疲民赖抚摩。
潇洒郡斋方在望，
飘摇征棹未能过。
拟求墨妙辉衡宇，
应有黄庭换白鹅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_224','伯兄由临海归省出示近诗次韵奉别','喻良能','宋','相别既四载，
相看如友生。
未成投辖饮，
先作倒衣迎。
夜雨方同听，
秋风又独行。
不堪分手处，
霜重雁行轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_225','初离鄱阳','喻良能','宋','三年劳簿领，
今日进归程。
意与长途远，
身兼薄縠轻。
板舆频送喜，
山驿屡逢晴。
道上人争指，
霜髭䌽戏荣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_226','判院蔡丈和予五诗次韵一篇奉酬','喻良能','宋','病起惊华发，
官閒觉素餐。
文章惭李益，
名誉羡苏端。
老去观书懒，
愁来避酒难。
非关作诗苦，
自尔带围宽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_227','即事','喻良能','宋','亦好经年别，
归来意转亲。
横斜花练练，
清浅水鳞鳞。
又逼瓜时戍，
聊娱戏䌽身。
新添兰桂圃，
近在岸西漘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_228','张使君生辰','喻良能','宋','绿茸红糁细团枝，
天上麒麟瑞此时。
风度冕旒尝见问，
威名草木自应知。
当年玉燕生燕国，
他日金貂侍汉墀。
再拜祝公何所似，
胜游长与赤松期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_229','李大著惠示诗卷次韵首篇为谢献之','喻良能','宋','辱赠舂容卷轴新，
悬知蚤岁擅诗声。
千林有韵霜风劲，
一点无尘霁月清。
细味班香兼宋艳，
自惭白俗与元轻。
欲哦恶语赓妍倡，
一夜昏花对短檠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_230','灵山寺','喻良能','宋','松竹声中寺，
山深人迹稀。
石从林背出，
云向屋头飞。
野鹿寒仍聚，
栖禽暮自归。
怪来襟袖冷，
浓翠湿征衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_231','陈知府体仁和予七夕试院诗并以龙涎数十饼为饷次韵奉酬陈每讲会甚盛','喻良能','宋','八郡经生满鳣堂，
那能斗酒博西凉。
晚年刻意玄虚讲，
蚤岁留心翰墨场。
怜我无毡寒坐客，
分公燕寝旧清香。
相逢一笑宁多得，
归去匆匆有底忙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_232','陈彦山寄示新诗次韵奉酬','喻良能','宋','山园宁厌小，
閒地只如馨。
木落长天碧，
云飞远岫青。
故人应见忆，
新咏许时听。
句好何劳琢，
虽搜不用冥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_233','侍太夫人拜扫先茔季直弟有诗因次其韵','喻良能','宋','东郊云气晓疏疏，
十里相携霁色初。
林幄尽头闻杜宇，
荇丝深处见王馀。
提壶相劝仍沽酒，
扶杖来观或荷锄。
不向如皋閒射雉，
真成一笑粲潘舆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_234','侍太孺人由安国过贤沙至凤池','喻良能','宋','板舆多乐事，
沙路及晴时。
约略瞻龙卧，
逶迤到凤池。
匏樽细斟酌，
华发足遨嬉。
此意安仁解，
曛酣更赋诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_235','侍亲由三山还东阳','喻良能','宋','南雪不到地，
玄冬偏满山。
春风仍料峭，
䌽袂正斓斑。
广厦千间静，
虚空一宿閒。
此身如羽翼，
飞倦始知还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_236','参议李郎中见和次韵奉酬','喻良能','宋','顷岁题名曲江院，
及肩曾许亚宫墙。
胸中阔贮云梦泽，
笔下浓薰班马香。
省直旧沾衾半白，
除书行见纸新黄。
和篇如出少陵手，
谁谓无心赋海棠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_237','叔度贤良再用游字韵见贻复次韵谢之','喻良能','宋','夕郎分阃镇东秋，
幕下挥毫秦少游。
一代风流今不泯，
百年文物尚堪求。
交情莫逆人谁似，
吟事方殷岁又遒。
他日约君为伯仲，
三间瓦屋住东头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_238','周少府由姑熟送余同宿于玩鞭亭','喻良能','宋','相别古桃郡，
相逢南豫州。
五年劳望眼，
一笑失离愁。
碧水溪桥暮，
西风野店秋。
追随成夜宿，
不为玩鞭留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_239','夜发曹娥堰','喻良能','宋','孤灯乍明灭，
隐约小桥边。
野市人家闭，
晴天斗柄悬。
秋深风落木，
夜静浪鸣船。
却忆前年事，
扁舟过霅川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_240','夜梦亦好园','喻良能','宋','薄宦思归切，
天涯秋气深。
一番南国梦，
千里故园心。
历历湖边路，
悠悠沙上禽。
横枝清绝处，
何日复追寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_241','奉和赵大本教授何处春深好二首','喻良能','宋','何处春深好，
春深倅贰家。
雨低檐外柳，
风度牖间花。
有意挥吟笔，
无心顾曲车。
慈颜一笑粲，
戏舞䌽衣斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_242','奉和赵大本教授何处春深好二首','喻良能','宋','何处春深好，
春深泮水家。
不妨频折角，
宁复误随车。
已见倾三峡，
行看判五花。
日边催觐速，
芝检紫泥斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_243','奉酬王宗丞用宿大木寺韵见赠','喻良能','宋','誉处千钧重，
文章一世雄。
诗工穿月胁，
檄好愈头风。
北岳关山碧，
南州荔子红。
使君今北海，
还许一樽同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_244','奉酬鲍仲山机宜见赠','喻良能','宋','四海今诗伯，
才名许孰俦。
波澜掩颜谢，
步骤到曹刘。
婉画参机幕，
精忠动冕旒。
时危须戮力，
谈笑复神州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_245','始生之日黎明以职事出郊','喻良能','宋','征鞍随晓色，
重露湿衣巾。
谁谓悬弧日，
翻为执辔辰。
野花工笑客，
啼鸟故窥人。
呼酒浇孤闷，
何心作好春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_246','府学职事置酒九仙以饯予行','喻良能','宋','玉友金朋三十三，
携尊相属向晴岚。
含毫共赋黄初句，
挥麈仍追正始谈。
再用清烟喷白泽，
更霏香雾噀黄柑。
俊游胜事真堪画，
华发飘萧只自惭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_247','松峭山傍偃松昔尝过之为赋长句今三十有六年矣复至其下慨然有感因次韵','喻良能','宋','人日肩舆度晓峰，
长松偃蹇倚晴空。
几年不见根如铁，
老境重来鬓似蓬。
独树未须誇老杜，
五楸那复论韩公。
青幢翠盖貌难似，
想见霏霏烟雨濛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_248','林明府携所和诗见过次韵奉酬','喻良能','宋','退之初过玉川家，
春径无泥草带沙。
几点飞来溪柳絮，
一番开尽海棠花。
窗间细雨青衫湿，
袖里新诗醉墨斜。
客散酒阑还掩户，
可堪明月满天涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_249','沿檄舟行出五云关','喻良能','宋','画舫朱帘出晓关，
便风飞过几重湾。
路经僧舍渔村畔，
身在烟霏雾霭间。
惊浪沸晴输远浦，
乱云拖粉露崇山。
偶因王事从心赏，
诗语匆匆不暇删。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_250','经理西山同二客二弟侄辈侍太孺人游观联句','喻良能','宋','西山仍复踞西台，
石径嵚崎此日开。
竹杖相邀七八客，
芳樽时釂两三杯。
瀑悬岩腹如飞雨，
石转山腰若隐雷。
敬侍慈颜供一笑，
陂陀坐稳兴悠哉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_251','罗春伯以吕居仁集寄似作诗为谢','喻良能','宋','平生子吕子，
妙语总关心。
忽得诗三百，
端胜书万金。
愔愔醒睡眼，
炯炯净烦襟。
何以报嘉惠，
空惭绿绮琴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_252','茂林见访有诗次韵奉酬','喻良能','宋','解鞍挥玉麈，
亹亹笑谈清。
昨夜灯花喜，
今朝乾鹊声。
兴同狂秘监，
诗似老弥明。
忆昔南台北，
相逢盖始倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_253','试院七夕','喻良能','宋','过雨秋风洒客裳，
长廊广厦更清凉。
不看云际痴牛女，
细读文中古战场。
病骨未轻聊把酒，
诗情欲适旋焚香。
敢辞秉烛分清夜，
犹记槐黄昔日忙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_254','试院九日次王茂材丞公韵兼呈翁沂伯广文','喻良能','宋','秋杪仍新霁，
天涯忆故乡。
少陵三坐客，
太白两重阳。
深院日复日，
寒花黄未黄。
昔年吹帽饮，
今日读书床。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_255','试院次韵马驹父见寄','喻良能','宋','华发萧萧知更稀，
回头五十四年非。
花添病眼正临卷，
春满故园犹未归。
止酒独醒陶靖节，
寄诗相忆谢玄晖。
若为比得新篇美，
西蜀江头锦一机。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_256','试诸生直庐书事','喻良能','宋','长日初随䌽线还，
阴阴帘幕曲栏干。
白袍三百近洙泗，
青桂两株如广寒。
下笔万蚕争食叶，
为文三峡泻惊湍。
谁知潦倒真无补，
不愧无毡愧素餐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_257','贤良马叔度和周内翰送予倅越诗见贻次韵奉酬','喻良能','宋','一鸣一息几千秋，
风翼端宜汗漫游。
笔底珠玑谁得似，
胸中云梦复何求。
谈馀正始人加胜，
诗比黄初语更遒。
西笑定应参儤直，
东游聊复伴遨头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_258','郊行','喻良能','宋','散策林塘路，
秋深别有光。
晦明云聚散，
浓淡树青黄。
晚觉衣襟冷，
风吹橘柚香。
菊花何处有，
聊欲试重阳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_259','雨馀','喻良能','宋','雨馀平野绿，
耕种满东皋。
处处鞭黄犊，
家家卖孟劳。
筠盘馈糠籺，
瓦碗荐溪毛。
所愿甘霖足，
梁间挂桔槔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_260','青岩道中','喻良能','宋','寒食江村路，
东风野渡航。
一篙春水碧，
两岸落花香。
飞絮匆匆远，
青山故故长。
兹游自奇绝，
底用更寻芳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_261','姜春坊以诗编见贻借题雪堂图韵作诗为谢','喻良能','宋','红颜话别浦边秋，
白发同为帝里留。
璧水庸庸参末坐，
春坊荦荦冠名流。
功名君且登麟阁，
出处吾行具钓舟。
饷我一编清似玉，
五言端的继苏州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_262','彦礼知丞上巳过访流觞于爱山之曲水','喻良能','宋','年来曲水竞流觞，
元巳夫君访草堂。
波撼石麟杯斝乱，
风翻花片笑谈香。
哦松适意清篇富，
闭户端忧白日长。
更约来年春好处，
重来相与醉沧浪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_263','思归','喻良能','宋','五载怀归不得归，
故园想像每依依。
蚕生村落桑黄长，
麦熟田家稚子肥。
谷鸟缓歌金缕曲，
箨龙浑著老莱衣。
一篇未就张衡赋，
漫向成均咏式微。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_264','既游东山乘月登舟至曹娥江','喻良能','宋','虞江波上一帆风，
天水澄明夜色空。
古体诗成岩影里，
新醅酒酌月明中。
咿哑两桨止还作，
欸乃数声西复东。
尘滓此时无一点，
恍疑身在水晶宫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_265','春水','喻良能','宋','磬湖春水夜来生，
晓起雷声逗雨声。
去马来牛心莫辨，
鸬鹚鸂鶒眼俱明。
飘零花片有底急，
摇曳柳丝如许轻。
旬月烟村半风雨，
榆钱好为买春晴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_266','春尽偶书','喻良能','宋','溪流如带碧萦纡，
满地閒花杂野蔬。
浓淡柘阴三月暮，
浅深山色晚晴初。
颇惊井落家徒壁，
却喜盘飧食有鱼。
蜀魄健啼春又老，
挥鞭吾亦忆吾庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_267','柳季修知丞以诗见贻次韵为谢','喻良能','宋','古木阴阴绕屋庐，
官居端的似田居。
诗清子厚龙城句，
字瘦诚悬殿壁书。
那复有心追四至，
只应无事富三馀。
一樽閒论金罍事，
为笑纷纷竭泽渔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_268','洪右相生辰','喻良能','宋','黄閤调元鬓未霜，
祇应书考似汾阳。
恳辞阊阖沙堤路，
暂乐蓬莱燕寝香。
茂烈未饶周叔虎，
英词宁谢汉班扬。
会看绣衮重催起，
快卷三江入寿觞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_269','洪右相生辰','喻良能','宋','凤将南吕入筒声，
节近中秋协气横。
玉燕呈祥生硕德，
金瓯覆字佐升平。
望同北斗泰山重，
操与秋霜烈日争。
昨夜清台占越分，
中台星带老人明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_270','盆池','喻良能','宋','小凿方池供醉吟，
才添斗水浪偏深。
莹心未数寒泉井，
明目何须寸碧岑。
树影落时清浸玉，
鱼鳞动处细浮金。
年来点检曾经汲，
唯有浇花趁日阴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_271','禹帝祠','喻良能','宋','几岁钦文命，
今朝拜禹陵。
稽山新雨霁，
鉴水暮云凝。
更睹玄圭锡，
悬知四载乘。
川灵洎河伯，
千古获依凭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_272','秋浦试院奉和马驹父见寄','喻良能','宋','也知融帐多馀暇，
欲往论文偶未遑。
弃置亡何投辖饮，
经营俱下读书行。
子云但觉玄犹白，
元亮应欣菊已黄。
辱赠清诗不知报，
剩亲灯火趁新凉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_273','草堂成即事二首','喻良能','宋','燕雀桑麻五亩匀，
香炉峰下磬湖滨。
青衫不碍两居士，
白发真成六老人。
子美浣花元不恶，
渊明栗里总宜贫。
作诗饮酒真吾事，
回首江湖懒问津。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_274','草堂成即事二首','喻良能','宋','三年留滞江之南，
归来故园寝亦甘。
经理草堂唐宝应，
耘锄荒径晋陶潜。
寸心自昔似南八，
双鬓只今如谢三。
手栽杨柳既合抱，
木尚如此人何堪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_275','送广漕曾郎中赴阙奏事','喻良能','宋','绿鬓怀中诏，
清秋向上都。
圣图方广大，
贤路不崎岖。
会见除清切，
宁须复转输。
公如任风宪，
抨劾莫踟蹰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_276','送王共父','喻良能','宋','西蜀东吴万里程，
偶然相值两浮萍。
黑头君已登三馆，
白发吾方醉六经。
夜幌论文灯耿耿，
春堤把袖草青青。
艅艎小别须回棹，
不用阳关肠断听。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_277','送交代李丞元举','喻良能','宋','蓝田松下日栖迟，
不比韩公作记时。
鹢首千行攀别泪，
牛腰几轴送行诗。
我无楚尾歌来暮，
君有齐民颂去思。
自是中年多作恶，
可堪烟雨话分离。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_278','送朱师古少卿归蜀','喻良能','宋','西蜀多贤士，
于今见奉常。
十年方出守，
万里好还乡。
峡水冬无险，
河图晚有光。
临歧分手处，
政尔不能忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_279','送伯寿兄之官上虞','喻良能','宋','平生艺苑笔同耕，
兄弟须知似友生。
三载方寻夜雨约，
六旬又作越中行。
举杯不学销魂别，
侧耳惟听报政声。
从此西冈数登眺，
白云飞处总关情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_280','送张使君','喻良能','宋','桐川风物最三吴，
刺史循良继两都。
但见卖刀还买犊，
谁知有裤本无襦。
来时竹马迎儿辈，
去日棠阴绕舍隅。
攀断车辕留不止，
他年应作祖张图。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_281','送陈给事帅四川','喻良能','宋','礼乐诗书一世英，
碧油青鬓二难并。
惯看词翰流三峡，
剩有精神驱五兵。
暂向坤维聊镇抚，
却归天阙致升平。
明年春水如天日，
䌽鹢乘风向帝京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_282','送陈给事帅四川','喻良能','宋','四海繁华一蜀都，
君王谋帅意渠渠。
百城赤子烦摩抚，
一代长材获展舒。
玉垒倚空充屏翰，
铁衣如洗护储胥。
裤靴帕首郊迎处，
想见旌麾入境初。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_283','送侍御帅夔府','喻良能','宋','西风动行色，
诗景绕征鞍。
赤甲悬危壁，
黄牛泻急湍。
猿声云背落，
山势马头盘。
天险须人守，
毋辞蜀道难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_284','送侍御帅夔府','喻良能','宋','湖海番君国，
江山白帝城。
凝香馀坐啸，
飞诏趣遄征。
誉处千钧重，
辎车一羽轻。
攀辕雪眉老，
送目逐双旌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_285','送侍御帅夔府','喻良能','宋','四海犹多事，
中原未版图。
皇心思启沃，
赤子望沾濡。
八阵难留滞，
三阶拱进趋。
茂弘宁有意，
江左待夷吾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_286','送侍御帅夔府','喻良能','宋','诸葛仍祠庙，
公孙只故基。
栋梁酣夕照，
雉堞蔓秋葵。
耿耿登临意，
悠悠今古思。
烹鲜不劳力，
馀事杜陵诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_287','送侍御帅夔府','喻良能','宋','千古楚东郡，
风流今在兹。
鲁公元直道，
文正不妨诗。
钳吏似束湿，
麾龙如使儿。
甘棠足遗爱，
会有去思碑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_288','送阎紫微归蜀','喻良能','宋','曲江分袂十年中，
一笑相逢楚水东。
西掖判花知思涌，
南墙哦竹坐诗穷。
秋风但觉艅艎驶，
昼绣何妨画戟雄。
道过夔门王内史，
为言双鬓已如蓬。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_289','送黄机宜叔愚归省四明','喻良能','宋','洒落孤标第一流，
笑谈倾座气横秋。
聊参机密东州幕，
曾与风流玉局游。
听雨忽惊形梦寐，
临风那肯更迟留。
橘堂想像多佳致，
恨不追参李郭舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_290','送曾大卿将漕江东','喻良能','宋','公去何尝负二宜，
要持玉节瑞明时。
江畿列郡皆争睹，
台阁名流总赋诗。
雕鹗暂为云外举，
凤凰终集上林枝。
近臣侍从多虚位，
会见回帆春色随。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_291','重阳咏菊','喻良能','宋','年年自赴重阳约，
不待陶家诗句催。
便欲急呼欢伯赏，
未知谁遣白衣来。
红萸有韵岳连湛，
素蕊无香赐望回。
何事杜陵嗔竹叶，
却教从此不须开。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_292','重阳遣兴','喻良能','宋','秋高身老少陵悲，
不独云飞雁亦飞。
红叶色深偏照酒，
黄花香重欲沾衣。
绝知落帽欢娱好，
最奈登山伴侣稀。
强插茱萸修故事，
未妨醉眼送斜晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_293','闻东嘉王公得杂学士喜而成篇','喻良能','宋','四海王夫子，
精忠简冕旒。
诏纶飞涣渥，
禁阁要名流。
江左思安石，
朝端欠武侯。
命圭兼召节，
蚤晚到南州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_294','除夕','喻良能','宋','夜永灯明岁又除，
依然坐冷乏氍毹。
平生潦倒如中散，
大半交游今左符。
未办黄精除白发，
渐惊玉水点银须。
欲论旧事无人共，
閒把香醪细细𣂏。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_295','宴饯逢寺丞口号','喻良能','宋','一扇清风自楚台，
公堂葱郁玳筵开。
旌幢映座千峰日，
鼓吹喧天万壑雷。
秋水几行挥玉箸，
春葱千指送金杯。
甘棠不独留遗爱，
会见翻为调鼎梅。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_296','展敬文孝庙','喻良能','宋','才昔高南国，
名今播八纮。
英姿留此地，
馀泽及编氓。
仙去江山在，
恩来日月明。
经从千载后，
款谒荐微诚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_297','席上','喻良能','宋','奉常珍重末僚情，
许以疏慵簉俊英。
已办初筵酬物色，
更将馀事到诗盟。
贪吟不惜挥貂笔，
忍醉何妨釂兕觥。
细踏芳菲过腴润，
桃蹊红雨报新晴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_298','挽司理奉议楼公','喻良能','宋','老烂为儒山泽臞，
半生辛苦就名誉。
三千白发身无事，
一点青灯夜读书。
真率杯盘如洛会，
崎岖岩壑似陶庐。
欲知老泪挥难尽，
洒遍霜飙更湿裾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_299','挽处士陈容','喻良能','宋','历数乡闾老，
谁知德齿尊。
无心游魏阙，
有意乐丘园。
漫不沾三釜，
真堪映九原。
涕洟歌楚些，
已矣莫招魂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_300','挽处士陈容','喻良能','宋','乾坤身老大，
丘壑迹委蛇。
不枉安车召，
谁为荐鹗词。
平生五千卷，
身后宁馨儿。
他日编遗藁，
应多感遇诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_301','挽石似之郎中','喻良能','宋','几作儒林冠，
亲承帝渥隆。
双旌大江左，
一节古吴中。
列宿英声在，
浮云旧事空。
无从挂吾剑，
老泪湿西风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_302','挽汤丞相汉国夫人','喻良能','宋','七秩芳名盛，
于今等逝波。
承天登宰辅，
看子掌编摩。
凤去青春独，
鸾回紫诰多。
他年彤管史，
兼述采蘩歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_303','挽县尉陈元圭','喻良能','宋','平生自负气雄豪，
落笔文词涌怒涛。
蚤岁贤关几雁塔，
暮年花县未牛刀。
凛然风义谁能并，
伟甚衣冠众所高。
我欲临风新执绋，
忍于绘事看青袍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_304','挽吴春卿舍人','喻良能','宋','出处平生似昔贤，
高风劲节凛朝端。
回天议论心无歉，
脱腕文章世所难。
斫铁叫天蛮獠服，
调羹满钵里闾欢。
定应直笔书英躅，
留与千秋后代看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_305','挽李靖少傅夫人','喻良能','宋','板舆曾至郑，
灵輤此归周。
霭霭云将夕，
亭亭月正秋。
九原开祔穴，
故土覆新丘。
岁晏寒松下，
茅苫孝子留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_306','挽周子及','喻良能','宋','洒落孤标迥不群，
胸罗星宿富多文。
两科擢第未为贵，
八事筹边堪策勋。
鲠亮谏辞端似贾，
崎岖宦路仅胜蕡。
我惭不执云溪绋，
空望云溪溪上云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_307','挽周判院','喻良能','宋','昔年胪唱下彤墀，
名压人头似牧之。
风动鳣堂昭武日，
化行雉径敬亭时。
曾无簪笔朝端用，
何以修文地下为。
我老不堪供执绋，
独将双泪逗瑶卮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_308','挽国史侍读李公仁父','喻良能','宋','大名垂宇宙，
秀气发岷峨。
学比渊云赡，
才方贾马过。
九朝资直笔，
二子振贤科。
已矣流芳在，
千秋保不磨。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_309','挽施州使君钟公','喻良能','宋','弱冠为儒世所推，
中年事业更瑰奇。
才名屡致诸公荐，
谠论深蒙睿主知。
郡政坚强同薤水，
行囊萧瑟似琴龟。
只今惟有清江路，
父老相逢说去思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_310','挽唐立夫舍人','喻良能','宋','才名振西蜀，
老气益中州。
草制追盘诰，
筹边动冕旒。
已令荣压角，
复遣饮遨头。
千古九江恨，
长随逝水流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_311','挽盐官县丞何公','喻良能','宋','先子生辛未，
齐年见此翁。
从容六纪内，
隐约古人风。
教子从书积，
延宾畏酒空。
阶前桃杏色，
依旧入帘红。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_312','挽高宗皇帝词','喻良能','宋','天地重开辟，
民人拱德馨。
奎文赞元圣，
宸翰列群经。
礼乐盈三纪，
光华亚九龄。
龙髯攀莫及，
臣子涕交零。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_313','挽高宗皇帝词','喻良能','宋','扈从浮江日，
忧勤立极初。
八年躬甲胄，
万国混车书。
治定端无竞，
功成自不居。
休明媲虞舜，
逸乐梦华胥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_314','挽商元鼎','喻良能','宋','举世方贪禄，
斯人祇自怡。
一官如涕唾，
半世足遨嬉。
心地陂千顷，
生涯酒一卮。
唯应郭有道，
吾不愧为碑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_315','挽黄泰之','喻良能','宋','汉世无双价，
皇朝第一流。
文章惊北阙，
名誉满中州。
槐市师模邃，
兰台史笔遒。
所嗟时未合，
不作济川舟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_316','挽提宫知丞周公','喻良能','宋','妙龄驰誉满东吴，
落笔骅骝走坦途。
四十年来鸣道学，
一千人内最群儒。
二松不负经纶志，
三径真成隐遁娱。
老我与君端莫逆，
遗文时阅漫长吁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_317','挽楼士特','喻良能','宋','平生易诸子，
向我独拳拳。
雪屋倾银斝，
春风并锦鞯。
笑谈多竟夕，
契阔未经年。
来作生刍奠，
凄凉涕泫然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_318','捕盗至栗洪岭下道人庵滞留数日遣兴','喻良能','宋','乱山深处小溪隈，
夏木阴阴水半回。
风岸攲斜对青竹，
雨枝低重弄黄梅。
浓愁难办新诗语，
吉耗聊倾浊酒杯。
戏䌽老人须强饭，
玉钩才吐即归来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_319','斋宿净明寺小饮易安斋口占','喻良能','宋','净明斋宿近初庚，
西蜀东吴一世英。
行径九盘山荦确，
流泉百折玉琮琤。
频飞兕斝颜俱渥，
细听犀谈座为倾。
觞咏直多幽兴足，
未应不饮似公荣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_320','晓行霜重如雪','喻良能','宋','霜重寒威一夜加，
晓来人迹板桥斜。
已看白雁来千里，
想见青州满百花。
何处菊枝犹复耐，
故园菊味定堪嘉。
慈颜正念征裘薄，
归去萱堂笑语哗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_321','晓霁','喻良能','宋','夜来细雨暗冥冥，
晓起秋容入画屏。
水色净涵天影碧，
林梢微露远峰青。
嫩黄稼卧衡从亩，
老翠柳拖长短亭。
一晌西风醒睡眼，
端如痛饮读骚经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_322','校官厅新栽岩桂','喻良能','宋','不将官舍等逆旅，
故把霜根栽绕墙。
他日花开映秋色，
何人手折惹天香。
丁宁护取森森碧，
想像匀排粟粟黄。
顾我疏慵百无取，
未应人错比甘棠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_323','海上作','喻良能','宋','晴浪空仍白，
云峰远更青。
乾坤几万里，
聚落一浮萍。
自昔闻溟渤，
从今小洞庭。
端如初发覆，
坐觉病眸醒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_324','留别伯寿兄','喻良能','宋','相过不惮远，
相迎慰所思。
须知对床处，
绝胜陟冈时。
夜雨论畴昔，
秋风惜别离。
明年楚东景，
准拟共题诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_325','留别赵明府','喻良能','宋','䌽棒漫分部，
牛刀新发硎。
花城方窃荫，
瓜戍已馀蓂。
生计双蓬鬓，
归心几驿亭。
他时重会面，
应是眼俱青。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_326','被郡檄祷雨丹井山徐真君祠登山拜毕即获霶霈追用韩文公郴州祈雨韵','喻良能','宋','欲解骄阳厄，
宁辞祀礼繁。
纯诚殚毣毣，
英烈仰言言。
云阵千屯合，
雷声万马奔。
晚来归路好，
飘洒势腾轩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_327','被檄之上饶言还未几又复往焉至小渡遇雨遣兴一首','喻良能','宋','檄至方云急，
吾行敢滞留。
朔风经小渡，
细雨过中洲。
冉冉新斑鬓，
飘飘敝黑裘。
欲知来往久，
三见月如钩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_328','读书','喻良能','宋','傍砌看黄奶，
临池诵子虚。
顾惭虽耗忘，
聊复惜居诸。
屋上两鸲鹆，
波间双鲤鱼。
疑他不识字，
何事也听书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_329','读玉局集','喻良能','宋','晓读苏仙集，
披翻未觉劳。
衙官视宋玉，
奴仆命离骚。
赤壁清风远，
黄楼逸兴高。
独嗟生苦晚，
不得侍挥毫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_330','读初寮集呈王宗丞','喻良能','宋','初寮文律冠中京，
晚岁深严三折肱。
清处月中仍聚雪，
高时风里政抟鹏。
家声不坠推王粲，
句法能传有杜陵。
剩作诗文追汉魏，
非公谁不阏溪藤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_331','读林公懿诚竹轩集次韵卷首一篇','喻良能','宋','南渡诗流复数谁，
为虞作乐只闻夔。
细看出胁穿心句，
想见裁云画月时。
此集自应传异域，
吾生还恨不同期。
先唐作者谁堪并，
奴仆微之辈牧之。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_332','通判孙宗丞分饷温柑次马抚干咏橘韵作诗为谢','喻良能','宋','珍果分柑不作疏，
李衡千颗直堪奴。
初尝蔌蔌泉流齿，
未摘青青香满株。
可是骚人怜楚树，
只应仙种自蓬壶。
龙城当日亲封殖，
还有霜苞似此无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_333','铅山','喻良能','宋','三月春风暖更飘，
满山嫩绿正娇娆。
几声劝我脱破裤，
何处撩人婆饼焦。
甘旨仅能供素发，
涓埃未有答皇朝。
吾庐渐近亦堪喜，
试把白醪倾绿瓢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_334','陪通守李丈出郊','喻良能','宋','出郭旌旗及晓晴，
朔风凛凛水泠泠。
堵墙野老瞻泥轼，
冠剑长松拂屏星。
破腊梅花强半白，
先春草色未多青。
经行肯为游观美，
王事驰驱不敢宁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_335','陪曹使君牧马寺劝农','喻良能','宋','朱轓小队出郊坰，
风捲浓阴作快晴。
夹道老人迎五马，
啭枝黄鸟避双旌。
参差麦垄云屯重，
零乱梅花雪片轻。
劝课定知非小补，
扶犁携饷趁春耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_336','寄宋子渊运使','喻良能','宋','对阁思槐市，
成规愧奉常。
六年谈笑阻，
千里梦魂长。
将漕衣仍绣，
空餐鬓已苍。
何当奉犀麈，
风月要平章。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_337','寄张君玉','喻良能','宋','橘亭一别五回冬，
寤寐何曾置此翁。
二十五声秋后点，
八千里外月明中。
夫君不寄平安信，
而我方栖簿领丛。
三峡江高天共远，
侧身西望兴何穷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_338','寄陈孟容二首','喻良能','宋','细草还堪藉，
柔荆亦可班。
驭风如肯过，
踏月不妨还。
种药临花畔，
分流绕竹间。
眼边无俗物，
颇似一瓢颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_339','寄陈孟容二首','喻良能','宋','先生湖海士，
馀子讵能班。
正始清谈近，
黄初美句还。
相望半舍外，
契阔数年间。
何日衡茅底，
匏樽一破颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_340','寄程教授士廓','喻良能','宋','去年同宴小重阳，
香雾霏霏橘半黄。
楚尾吴头双妙丽，
茱枝菊蕊总芬芳。
十分满釂白衣酒，
两袖浓携燕寝香。
回首只今如梦寐，
暮云烟浪正微茫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_341','寄题梅山','喻良能','宋','平生满耳说梅山，
十里荷花缭绕间。
宫女三千颜绰约，
绣衣十万䌽斓斑。
濒江景好图难尽，
飞鹭诗工语莫删。
定约后期穷胜赏，
不辞和月棹船还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_342','悼吴居厚','喻良能','宋','学问从来著月评，
慈恩何事欠题名。
贤哉难老堂虽就，
惜也陈情表未成。
畴昔几回同把酒，
于今一涕独沾缨。
张公当日称操履，
江汉伤心昼夜倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_343','晚行竹山道中','喻良能','宋','山瘦溪如练，
丹青见亦稀。
乱鸦将影过，
孤鹜带霞飞。
秋色此时老，
故园何日归。
西风吹独立，
搔首怯征衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_344','曹务拘缀不及赴张持荷赏梅之约因得小诗寄似','喻良能','宋','渺渺烟波阔，
南湖在帝城。
梅将春共早，
人与境俱清。
笔墨探三昧，
樽罍有四并。
未能乘兴去，
遥望目增明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_345','检书偶见故王侍郎嘉叟旧与余倡和之什良用慨然因题四韵','喻良能','宋','文字名三世，
精神运五兵。
徒看遗墨在，
却叹曲池平。
浙右频犀麈，
江东几兕觥。
倡酬今已矣，
抚卷泪纵横。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_346','谒太平兴国宫','喻良能','宋','平生耳满太平名，
今日身亲谒太平。
道子画图形未泯，
庐君山水眼初明。
雨馀翠滴千峰色，
秋半寒生万壑声。
扣石当年开洞府，
傥容凡骨到蓬瀛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_347','雪','喻良能','宋','密雪乘风逞素肌，
穿窗透隙入帘帏。
漫空隐隐琼瑰屑，
乱眼纷纷鸥鹭飞。
三客新成梁苑赋，
六花又舞谢庄衣。
回思拜表明光罢，
携得香烟满袖归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_348','雪','喻良能','宋','长风永夜搅青冥，
晓起寒光乱眼凝。
回旋舞空端入画，
飘萧著水自成冰。
松篁被练三千士，
冈阜瑶台十二层。
茆舍倍添薪火费，
只因无事读书灯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_349','黄讲书太器见和五诗次韵一篇奉酬','喻良能','宋','客毡寒莫致，
官舍总萧然。
睡思茶甘外，
穷愁酒力边。
未成投辖饮，
时作拨书眠。
野鹤如双鬓，
衰迟祇自怜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_350','黄泰之郎中以潮阳诗见贻次韵一篇奉酬','喻良能','宋','千里潮阳喜政成，
五年重会帝王城。
尺书不寄头俱白，
一笑相逢意已倾。
辉采共看新列宿，
风流犹记古州瀛。
诗编总是惊人语，
怪得年来太瘦生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_351','喜待制王丈归自夔门','喻良能','宋','三年遥望瞿塘峡，
独立西风首重回。
一骑翩翩飞诏去，
片帆渺渺下江来。
平生不愿侯万户，
今日重欣酒一杯。
闻道日边催觐速，
不须归路更徘徊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_352','喜雪','喻良能','宋','同云生旧腊，
积雪入新春。
野色连沧海，
驩声动紫宸。
峰峦朝掩映，
楼阁夜精神。
莫展山阴画，
虽工不是真。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_353','寒食游香山','喻良能','宋','杖藜随所适，
花柳自村村。
野岸桃临水，
人家竹映门。
香泥飞燕子，
芳草思王孙。
著处堪沈醉，
春醪正满樽。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_354','景德道中口占','喻良能','宋','捧檄东方日，
芳春未及归。
路花红掩映，
溪树绿因依。
鸟语催寒食，
人烟接翠微。
寻诗忘远近，
细雨湿征衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_355','朝爽之前瑞竹忽生','喻良能','宋','好竹逾千个，
数茎忽发生。
月明连理影，
风细合欢声。
矫矫双鸳举，
翛翛两凤鸣。
祇应三昧手，
䌽笔画难成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_356','游下岩过松峭祠傍偃松又赋长句','喻良能','宋','谁将秋色替云峰，
万里炎歊一洗空。
细雨复青池上草，
西风顿白鬓边蓬。
聊同吾党二三子，
来访山中十八公。
更拟夜深乘月到，
要看香雾共冥濛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_357','游西源','喻良能','宋','万里西源路，
秋风屐齿鸣。
嶙峋千障碧，
窈窕一川清。
天柱云霄迥，
香炉雾霭轻。
何当携翠袖，
重遣酒壶倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_358','游西源于白云峰下烟霏雾霭间逢一女子缟裙翠袂玉雪可念同游十有二人遂共酌酒于大石屏季直弟有诗因用其韵','喻良能','宋','相携摄履响层峦，
翠蔓苍萝著处攀。
身在天台秋色里，
路经巫峡暮云间。
欲飞还住一仙子，
似淡如浓双远山。
笑尽一樽无处觅，
断肠雾鬓与风鬟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_359','登五峰亭望庐山','喻良能','宋','平生庐阜去无因，
咫尺于今不得亲。
顾我尘劳四十九，
羡他萧散二仙人。
会当拄颊看山色，
更欲题诗满涧滨。
为报草堂莲社友，
扫云开户待游轮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_360','紫笑','喻良能','宋','表里俱秾紫，
冬春独擅青。
每蒙天一笑，
不与素同馨。
风味撩吟笔，
芳非入画屏。
几番饶睡思，
闻此洒然醒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_361','紫霄宫','喻良能','宋','间关穿木杪，
诘屈转山腰。
自昔形清梦，
于今到紫霄。
容仪粲冰雪，
环佩响琼瑶。
安得顾吴手，
凭渠图素绡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_362','腊八日雪参议林郎中有诗因次韵','喻良能','宋','玉树参差见，
银花子细看。
淖糜分腊序，
圆炭度朝寒。
冉冉头新白，
匆匆岁又残。
聊凭一杯醉，
忍把两眉攒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_363','谢中书施舍人宴集','喻良能','宋','紫微高义笃同年，
邃宇开筵近腊寒。
绿蚁醅浓粘玉盏，
紫驼峰美照金盘。
醺酣上颊生春意，
文字清谈卜夜阑。
更辱盘飧馈黄发，
顾惭珍报乏琅玕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_364','谢张使君惠簟','喻良能','宋','瘦玉敲风翠干长，
织成漪浪莹沧浪。
封题尚带鄱江润，
卷赠犹馀燕寝香。
竹笛当年同秀质，
桃笙何处避寒光。
微躯讵足当珍赐，
持奉亲闱枕扇凉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_365','谢赵昌父投赠诗卷','喻良能','宋','赵子有新作，
鼎珍初出庖。
端能工竞病，
宁复费推敲。
白战应难敌，
清臞亦任嘲。
风流前辈尽，
试合续弦胶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_366','鹅湖寺','喻良能','宋','长松夹道摇苍烟，
十里绝如灵隐前。
不见素鹅青嶂里，
空馀碧水白云边。
氛埃斗脱三千界，
潇洒疑通十九泉。
五月人间正炎热，
清凉一觉北窗眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_367','鹅湖寺','喻良能','宋','水鸟飞来一问津，
璧宫珠塔便红尘。
开基古佛留遗像，
直日奇峰列众宾。
芋火拥残知永夜，
霜钟递起向初晨。
川徒渺渺驱尘驾，
回首林前愧野人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_368','叠嶂寒溪砚屏','喻良能','宋','叠嶂千重秀，
寒溪十里清。
渔舟朝欸乃，
樵斧昼敲铿。
窈窕疑身到，
幽奇讶笔精。
萧斋凝睇久，
坐觉世情轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_369','摄邑狱空','喻良能','宋','番邑于今剧，
民风自古雄。
琴堂惭久摄，
剑狱喜新空。
纆索尘埃里，
桁杨片段中。
使君端不扰，
顾我百无功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_370','新安遇雪','喻良能','宋','寒色今朝异，
屯云万里同。
定知花剪水，
不是絮因风。
薄宦翻成旅，
愁吟未易工。
白头亲八十，
留滞楚江东。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_371','献之大著得予喜赋以诗来谢次韵奉酬','喻良能','宋','夺袍吟处笔，
垫角雨馀巾。
黄绢才无敌，
青藜杖有神。
将乘桓典马，
肯受庾公尘。
老我知何幸，
穷涂获卜邻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_372','筠溪','喻良能','宋','精舍仍幽处，
深溪冒浅篁。
寒声随浪起，
翠影共流长。
断岸通秋月，
虚檐受夏凉。
虽无杜陵韵，
绝胜赞公房。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_373','签厅落成为赋长句','喻良能','宋','幕中英俊许谁先，
一一骅骝拟著鞭。
老我漫誇森画戟，
夫君端称泛红莲。
鸠工已见成轮奂，
载酒何妨醉圣贤。
闻道公馀多暇隙，
定持椽笔籋云烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_374','遣兴','喻良能','宋','山园近寒食，
春事总芳菲。
风暖鹁鸪语，
日长蝴蝶飞。
花光明醉眼，
草色净尘衣。
自足家居乐，
为生未觉非。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_375','鉴湖道中口占','喻良能','宋','轧轧篮舆鉴水滨，
水纹如染草如茵。
繁红零落徐娘老，
远翠低徊西子颦。
犹及残春追胜赏，
不妨馀事作诗人。
胸中磊磈须浇洗，
未厌伤多酒入唇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_376','锦园','喻良能','宋','孟夏锦园好，
山花高下开。
风攲红芍药，
雨重紫徘徊。
衣染香边蕊，
鞋粘绿处苔。
莺歌兼蝶拍，
时送掌中杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_377','锦园','喻良能','宋','山园多胜践，
缭绕磬湖滨。
畦药青生甲，
湖波绿动鳞。
鹁鸪知欲雨，
鸦舅报将晨。
却忆京华日，
长怀浩荡春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_378','锦园双桂植之二十八年未尝著花今忽盛开紫趺黄蕊所未曾见喜而赋诗','喻良能','宋','畴昔栽双桂，
于今四七秋。
紫趺香冉冉，
金蕊色浮浮。
标致殊他桂，
风流最蓐收。
无才强摹写，
著语故难遒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_379','端午至太平寺','喻良能','宋','客里逢端午，
僧廊雨气凉。
筼筜千个碧，
薝卜六花香。
鲁頖程尤远，
潘舆兴自长。
糁蒲倾美酒，
笑入醉中乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_380','裴园小集郑汝谐同年有诗次韵奉酬','喻良能','宋','慈恩雁塔题名处，
回首端如梦寐中。
千里远从当日别，
一樽重喜此时同。
飞腾我久钦公辈，
潦倒君当恕此翁。
异日尚期尘史册，
事功那敢废磨砻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_381','题九华山用太白联句韵','喻良能','宋','千古池阳郡，
九峰应最华。
明珠绚晨露，
丽绮粲晴霞。
岭头过子晋，
岩腹憩洪崖。
谪仙无复见，
空想夏侯家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_382','题三洞','喻良能','宋','千古巢仙地，
嵌空本自然。
一看三叹息，
十步九留连。
似入华阳洞，
疑通小有天。
何时洗尘垢，
来作枕流眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_383','题云黄山宝林寺','喻良能','宋','弥勒下生地，
溪山秀且长。
萧萧双树碧，
冉冉片云黄。
晓日觚棱净，
西风松桂香。
十年疏杖屦，
玉石耿难忘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_384','题开先寺','喻良能','宋','壮观端宜冠九州，
未应万壑敢争流。
尽将银汉为悬瀑，
一洗红尘变凛秋。
白雨廉纤飞迥野，
玉龙夭矫下灵湫。
庐山处处虽奇绝，
不到开先未是游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_385','题开先寺','喻良能','宋','少年魂梦到庐山，
今日亲游鬓已斑。
聊复挥毫吟紫翠，
未妨拄颊对孱颜。
遥看飞瀑三千丈，
近去青天咫尺间。
不为白云频属念，
应游此地不知还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_386','题东山谢安石故居','喻良能','宋','江边潇洒东山寺，
知是曾经谢傅游。
一代英姿馀信史，
千年陈迹付东流。
暮云初致苍生恨，
远翠如凝妓女愁。
好古嗟予生苦晚，
停桡明月满沧洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_387','题冯家洞','喻良能','宋','空岩寒气凛兢兢，
入户神清思亦澄。
似应如非声澒洞，
已垂未落石崚嶒。
深于豳俗藏冰室，
险过文王避雨陵。
刮藓磨崖书淡墨，
胜游聊复记吾曾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_388','题归宗寺','喻良能','宋','寺因逸少曾为宅，
峰自秦皇已得名。
不独山南称最古，
故应江左号尤清。
路趋绛阙山梁险，
奁隐金轮石镜明。
谁信尘埃倦游客，
西风还许杖藜行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_389','题何茂宏茂恭林堂','喻良能','宋','华堂閟林樾，
林秀水泉甘。
野色袁家渴，
秋声钴鉧潭。
二难今有此，
四者许谁参。
他日承明直，
悬知忆翠岚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_390','题秀野堂','喻良能','宋','秀野临空阔，
三堂若是班。
荷香平入座，
湖影倒涵山。
鱼鸟丹青里，
云烟水墨间。
他年傥同社，
应共狎鸥閒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_391','题周希稷清閟轩','喻良能','宋','之子蕴琅玕，
幽轩足考槃。
茏葱烟翠湿，
琐碎日光寒。
似向兰亭见，
全胜墨本看。
是中虽信美，
未可懒弹冠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_392','题建德驿用经略张舍人壁间韵','喻良能','宋','残暑涂山去，
凉风至德来。
吟馀秋色老，
客里菊花开。
传舍全依石，
中庭半是苔。
张公有佳句，
三复兴悠哉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_393','题祥符寺灵山阁','喻良能','宋','一倚危栏已快哉，
俯看屏障掌中开。
江间碧浪循城去，
天外青山入座来。
隔岸几声闻鼓角，
傍林千簇见楼台。
白云只在孤飞处，
西望关心首重回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_394','题绣川驿揖秀亭次张明府韵','喻良能','宋','一色苍波百顷烟，
直楣横槛覆华椽。
从来好景无今日，
何限清诗似昔贤。
把盏有山来酒面，
凭栏无路到愁边。
我来政值雨新足，
芳草芊芊绿满川。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_395','题郭邵州同尘庵','喻良能','宋','荣辱酣歌里，
贤愚睡眼中。
未应分野马，
那复障西风。
晏坐从凝席，
扬鞭任软红。
岩栖兼鼎食，
处处不妨同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_396','题隐静寺','喻良能','宋','杯渡已仙去，
兹山馀胜踪。
傍云开广殿，
夹道荫长松。
幽洞秋含雾，
清溪冷浸峰。
老僧如宿昔，
一笑喜相逢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_397','题雪峰寺','喻良能','宋','兰若接闽天，
登临意豁然。
楼台秋色里，
钟梵暮云边。
未遂游山兴，
聊为借榻眠。
白头仍捧檄，
奔走只堪怜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_398','题确山梵安寺','喻良能','宋','确山风物似齐山，
谁著精蓝乱石间。
僧梵四时看紫翠，
轩窗终日对孱颜。
暂容借榻松风惬，
更欲题诗藓壁悭。
老我还思十年事，
飞来峰上晓跻攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_399','题颜范祠堂','喻良能','宋','圣宋神唐两钜人，
高风劲节许谁伦。
闉阇自昔宜双庙，
轮奂于今始一新。
破敌威名优魏国，
偃藩功业过张巡。
后先来作江城守，
俱障西风避庾尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_400','磬湖之侧累拳石为山岩谷幽邃有巫庐台霅之趣因成短篇','喻良能','宋','背湖临槛碧崔嵬，
万壑千岩咫尺开。
坐觉巫峰天际落，
忽惊庐阜眼中来。
地偏未害心还远，
潭小何妨水自回。
竟日相看两不厌，
老夫真个似童孩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_401','赠陈宣干','喻良能','宋','嗜古心仍切，
寻诗句益工。
十年江左别，
一笑日边同。
补外吾天幸，
怀归子道东。
好为旬朔款，
解榻待春风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_402','赠楼尉','喻良能','宋','谁识尊前戏䌽身，
须髯如棘鬓如银。
久为朝士空餐甚，
又见秋声满耳新。
元亮祇思三径乐，
子云何事九衢尘。
襟期兰契如君少，
未可匆匆动去轮。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_403','衢右道中','喻良能','宋','投晓行衢右，
经旬别楚东。
侵衣梅溽雨，
吹面麦秋风。
垄亩凝烟外，
峰峦滴翠中。
悬知乡井近，
渐喜语音同。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_404','衢右道中','喻良能','宋','渐喜家居近，
相望六驿间。
脱身江左役，
洗眼浙东山。
乡味初充馔，
慈闱亦破颜。
经过縠溪水，
应笑鬓毛斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_405','东宫生辰','喻良能','宋','宝历天重启，
皇图日寖昌。
九重资燕翼，
万国仰元良。
玉律秋初杪，
金飙岁正穰。
前星辉采盛，
少海庆源长。
甲观祥烟滃，
春宫协气翔。
千秋佳节胜，
四荚瑞蓂芳。
瓜枣欣初献，
蟠桃庆乍尝。
庭罗六佾舞，
天荐九霞觞。
银榜弥生耀，
铜扉粲有光。
欢声连紫极，
喜气溢穹苍。
册锡雕珉焕，
旗颁青辂扬。
衣惟珍黻冕，
音不嗜宫商。
问寝同周发，
隆师过汉庄。
猷为规禹启，
翰墨掩钟王。
化被宾詹属，
恩沾左右坊。
善三今独冠，
明两古难方。
陆贽言犹采，
宣尼训敢忘。
本支绵百世，
羽翼贰岩廊。
宿忝宫僚旧，
曾沾兑泽滂。
愿斟沧海酒，
岁祝寿无疆。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_406','由上饶之贵溪舟中书事','喻良能','宋','日月三秋杪，
江山万象殊。
小舟浮舴艋，
广信出闉阇。
草木关诗律，
云烟入画图。
水清沙可数，
景好句难摹。
汀际寒鸣雁，
樯端晚噪乌。
樵村人语静，
商棹夜灯孤。
冷水寻宵泊，
焦滩就晓餔。
雾销分浦溆，
风定少帆蒲。
爱日生篷背，
奇峰涌坐隅。
芙蓉多落蒂，
杨柳有枯株。
枫叶红绡剪，
芦花白雪铺。
翩翩两行鹭，
泛泛一双凫。
断岸几千尺，
诛茅间一区。
鹚岩清港急，
龙濑碧涛粗。
断已凭三老，
那能贵一壶。
酒垆劳问讯，
渔艇费招呼。
鲜鲫还堪买，
香醪亦任沽。
不妨成酩酊，
聊复免驰驱。
汭口真萧镇，
钱仓岂旧炉。
丛篁惊外裹，
怪石觉中刳。
渐喜三吴近，
宁辞十里纡。
波平如泻镜，
罡密似连珠。
啸咏知谁和，
攲眠只自娱。
市声喧弋邑，
山雨闹莲湖。
拟傍桃花宿，
容翻贝叶无。
鸟栖方舣楫，
鲸吼又乘桴。
野菊新收艳，
官梅未吐须。
贵溪端爽洒，
贱子小踟蹰。
王事三旬外，
舟程六驿逾。
更判弦月上，
应得䌽衣趋。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_407','夜宿浮石山崇福寺上方题壁','喻良能','宋','窈窕寻支径，
萦纡度密林。
岸回溪更驶，
峰转坞逾深。
僧梵云边寺，
钟鱼竹里音。
解鞍生妙兴，
倚槛净烦襟。
永夜凉飙动，
初秋爽气侵。
岩空寒溜滴，
壁静候虫吟。
香篆窥孤宿，
灯花伴独斟。
不谙尘外趣，
谁识此时心。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_408','试院中秋效诸进士作月涌大江流','喻良能','宋','团月临清夜，
平分一半秋。
轮侵斜汉迥，
色涌大江流。
皎皎惊飞鹊，
亭亭喘卧牛。
一川寒练静，
十顷素光浮。
碎彩通袁渚，
馀辉谢庾楼。
翻思杜陵老，
岸草泊樯舟。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_409','送江充之郎中知温州','喻良能','宋','岩廊拱神圣，
岳牧用才良。
委寄晋藩镇，
飞腾汉省郎。
缣推非矫激，
绵蕝岂寻常。
花粲挥毫玉，
风生漱齿霜。
儿童骑截竹，
父老候甘棠。
五马晴薰细，
双旌晓月凉。
清香凝燕寝，
春草梦池塘。
乳哺苏民瘼，
生薪束吏行。
谢楼山色净，
孤屿海天长。
信美毋多恋，
遄归觐建章。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_410','送赵达明太社知江州','喻良能','宋','天上佳公子，
人间少吏师。
文华绅笏服，
名字冕旒知。
剸决监州日，
舂容栗社时。
未成持从橐，
聊复把州麾。
京邑期蒙福，
湓城望宠绥。
朱轓临境土，
竹马走童儿。
去兽同均辈，
蠲逋继浚之。
政成遄入觐，
献纳日论思。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_411','桐汭','喻良能','宋','东汭波吞岸，
西桐水见沙。
祠山千古盛，
州宅四时嘉。
前直三峰峻，
旁连大洞呀。
黄南清港曲，
织女小桥斜。
野店篱为户，
春山茧作花。
乌羊难入馔，
青果颇宜茶。
绷锦饶新笋，
枪旗富嫩芽。
灵山古佛地，
丹井列仙家。
铁冶名犹壮，
金牛迹尚洼。
滞留三载久，
诗板满烟霞。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_412','留别王状元二十四韵','喻良能','宋','才大文章伯，
忠纯社稷臣。
七州钟秀异，
孤屿赋精神。
德蕴圭璋润，
胸涵海岳春。
麟经频得隽，
槐市早称珍。
宿弊时方革，
皇纲上正亲。
大廷清问降，
空臆谠言陈。
力补严宸衮，
深撄睿主鳞。
一元追董相，
多诈耻平津。
文擅无双价，
胪传第一人。
声华飞宇宙，
风采耸簪绅。
贵纸宁堪数，
回天仅足伦。
施行均令甲，
奖谕见丝纶。
未覆金瓯墨，
聊为绿水宾。
爱民如赤子，
束吏似生薪。
鉴水书题遍，
稽山赋咏频。
却梅清节著，
诬狗滞冤伸。
贱子嗟何幸，
同年盖宿因。
糟糠聊摄局，
山水获联茵。
醇酎容沾醉，
新诗许效颦。
独蒙青眼旧，
端异白头新。
酬倡几千首，
从游殆十旬。
笑谈将契阔，
肝胆政轮囷。
帝梦方思说，
天民伫起莘。
不才虽苦窳，
终始愿陶钧。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_413','湖上用王茂材同年韵','喻良能','宋','木落长空净，
秋深爽气多。
澹烟浮远树，
晶日泊平蓑。
小艇浮深碧，
孤筇曳慢坡。
菊花簪雪鬓，
桑落滟金荷。
妙兴追潘岳，
清游轶永和。
何当命菱角，
唱我醉时歌。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_414','释奠礼成上安抚大观文十四韵','喻良能','宋','钜宋中兴日，
全闽极治年。
保釐须硕德，
镇抚赖真贤。
燕寝何曾逸，
儒宫最所先。
上丁将蒇事，
仲月乃修虔。
铏鼎参罍洗，
牺尊间豆笾。
低昂衮绣服，
拜起冕旒前。
庭燎明如昼，
炉薰滃似烟。
向风人引领，
观礼士填咽。
阖郡欢声沸，
熙朝盛事传。
僖公甘避路，
常相敢差肩。
宜有新诗播，
庸昭美化宣。
陋儒何幸会，
典礼获周旋。
南纪非工部，
中和岂子渊。
斐然形颂述，
深愧采芹篇。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_415','题东林寺','喻良能','宋','江湖大兰若，
庐阜一东林。
砌绕琮琤水，
门罗翠碧岑。
烟云千古色，
松桧四时阴。
岸帻销尘虑，
凭栏净客心。
殿成神运力，
泉出虎跑音。
溪在思元亮，
堂荒忆醉吟。
图传三笑粲，
阁拥五杉森。
贝叶应难访，
经台已莫寻。
僧袈何代朽，
佛影几时沉。
晋辇黄埃久，
殷碑苍藓深。
不妨閒吊古，
谁复为沾襟。
香火惟莲社，
传流直至今。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_416','七峰亭独坐','喻良能','宋','雨霁失炎燠，
新亭境清淑。
层波绿奫泫，
叠嶂青陆续。
风篁韵丝桐，
烟柳开画轴。
澹然尘虑销，
庶足永曛旭。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_417','二月二十一日何司业集客于张园玉牒给事命予赋诗紫微舍人左史舍人亦以见委因成七言十韵一首','喻良能','宋','寒食初过天气佳，
帝城名园绿藏鸦。
白绵红雨互飘泊，
莺啼燕哢纷交加。
司成领客当暇日，
不惜醉脸生红霞。
坐中宾客皆贤豪，
一一圭璧无纤瑕。
夕郎风采照今古，
封驳不贷奸与邪。
紫微笔语妙天下，
文锋凛凛森莫邪。
左史声名动六合，
岂特畴昔传三巴。
一朝樱笋德星聚，
离骚可奴玉可衙。
兰亭觞咏仅堪比，
金谷歌舞徒能奢。
我有一匹好东绢，
谁为作图千古誇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_418','二月二十四日杨廷秀郎中诸友约游西湖余以小疾不至分韵得子字','喻良能','宋','都城西头二月尾，
湖水平堤縠纹起。
南北山光罨画中，
浅深草色裙腰里。
群仙领客泛艅艎，
黄帽劈波惊鰋鲤。
中流剧谈闻两岸，
阖坐题诗动盈纸。
如渑自足醉朋从，
馀沥犹能沾走史。
当年曲水迹已陈，
此日渼陂欢莫拟。
蹇予小疾独不至，
诗伯索诗殊未已。
笔已老矣何能为，
但诵西湖比西子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_419','二月十五日陪府公出郊劝农','喻良能','宋','雨过郊原草色匀，
元戎小队出城闉。
聊穿阡陌沟塍路，
遍劝锄耰袯襫人。
红杏梢头春意好，
绿杨深处鸟声新。
此行端为劭农设，
肯学醺酣吐锦茵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_420','八月十五夜玩月','喻良能','宋','前年磬湖新雨歇，
独绕湖边待明月。
夜深云散月华来，
疑是山阴踏晴雪。
去年锁宿校群英，
冰娥于人亦有情。
仰看一镜缘云上，
俯听春蚕食叶声。
今年广文在官舍，
亦复开樽临月榭。
慈颜一笑䌽衣轻，
谁云官冷孤清夜。
酒阑月色更徘徊，
捲帘开户真佳哉。
悬知明年应更好，
扁舟正泊双溪隈。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_421','十月五日从兄四弟三侄侍太孺人赏菊亦好园以赏心乐事为韵分得赏字','喻良能','宋','霜天豁澄明，
水日共清朗。
西园足甘菊，
欢言事幽赏。
板舆奉慈颜，
华发森少长。
一笑喜团栾，
千枝迷俯仰。
黄英浥露繁，
翠蔓缘篱上。
雄蜂与雌蝶，
采撷纷还往。
逸兴既中酣，
佳致仍外奖。
未多彭泽贤，
不羡天随广。
忆昔吏江东，
王事困鞅掌。
及今处闾里，
暇日娱垲爽。
殽酒虽不丰，
献酬非或强。
分韵先阿连，
作诗真技痒。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_422','三月十四日陪同年十有六人游净慈遂饮于水月居坐中即事','喻良能','宋','美酒未尽双玉瓶，
更听提壶鸣不停。
斜阳可饮径须饮，
趁得城门打鼓声。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_423','三月十四日陪同年十有六人游净慈遂饮于水月居坐中即事','喻良能','宋','车驰卒奔风雨过，
粉白黛绿春事妍。
裙腰政佳酒仍美，
那复有路到愁边。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_424','丫头岩','喻良能','宋','自有宇宙有此山，
万八千岁须臾间。
亭亭造天屹石壁，
雨淋日烁逾坚顽。
且无泉瀑美裙帨，
肯以草木媚容颜。
丫头得名良未称，
那有巨手梳髻鬟。
会当呼作陆砥柱，
长与羲娥阅往还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_425','大雪','喻良能','宋','山阴境中寒雪飞，
山川明秀见应稀。
严威不贷乘兴棹，
馀彩并入翻书帷。
黄竹应歌姬满曲，
素花又舞谢庄衣。
东郊薪者寒到骨，
纵有狐裘那忍披。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_426','大雪追和退之辛卯年雪韵','喻良能','宋','太皞亦已至，
玄冥犹未归。
茫茫天壤间，
浪阔银山围。
玉龙横梅度，
皓鹤漫空飞。
白帝有所适，
飘飘扬旌旂。
从者一何繁，
缟席仍练衣。
招邀姑射仙，
逢迎广寒妃。
祥耶时令耶，
畴能测天机。
饥人冻欲死，
赏玩理则非。
安得万裘褐，
寒者或庶几。
愿言均此惠，
不知身贱微。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_427','己亥中秋','喻良能','宋','二七月皎皎，
三五云沈沈。
终然露半璧，
亦复牵孤吟。
夜久群动息，
唯有寒蛩音。
长年重节序，
感慨非独今。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_428','广信试院追和东坡催试官考校韵','喻良能','宋','深院锁凉秋，
西风坐间好。
几净窗明尘不飞，
似蹑红云至三岛。
数枝淡淡桂新香，
千带垂垂柳初老。
此邦天下秀，
多士邹鲁无。
负薪或解谈王道，
被褐无非怀璧夫。
五兵夺目库观武，
大嚼快意门过屠。
谁言扳才古难必，
披沙求金要须得。
回思裹饭然脂烛，
一心敢拟思鸿鹄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_429','中秋望月偶诵唐欧阳詹玩月诗追和一首','喻良能','宋','云净天既碧，
境幽月逾光。
未数钴鉧潭，
不羡桂子堂。
霏霏香雾横，
蔼蔼明辉扬。
冥搜兴乍酣，
徙倚夜未央。
走兔望圆魄，
飞鸟喜新凉。
但知整纶巾，
何用翻霓裳。
芳尊聊自倾，
玉盘欲谁将。
美人何时来，
渺渺天一方。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_430','为何监狱题种德堂','喻良能','宋','作堂备登览，
既作扁其颜。
扁颜固云易，
践名良独难。
我友何水曹，
筑堂水云间。
瞰临擅奇绝，
佳气何郁盘。
横以数亩池，
缭以四面山。
石楠间女贞，
青士依苍官。
纷纷杂花卉，
栽植日以繁。
岂独秀春融，
未应凋岁寒。
凭栏试游目，
皎皎万虑宽。
张公江海客，
一见颜为欢。
嘉名揭种德，
寓意固有存。
期君宴游日，
内照时返观。
善性益培壅，
芜累须一删。
木老德亦熟，
无忘老坡言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_431','为周提宫题尚友堂','喻良能','宋','先生高节昭流俗，
未应名宦能羁束。
归来卜筑傍泉石，
洒落轩楹照山谷。
外罗君子六千人，
中有插架三万轴。
我尝一日坐其间，
至今清兴犹堪掬。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_432','为柴怀叔殿院题世䌽堂','喻良能','宋','庆积门阑久，
祥钟家世醲。
乘骢惊创见，
戏䌽觉重逢。
鲐耋频三喜，
孙曾见八龙。
年龄开九秩，
孙子享千钟。
奕叶今荣耀，
蝉联旧素封。
家风追万石，
眉寿拟三松。
画栋侵银汉，
平池浸碧峰。
同心木芍药，
并蒂水芙蓉。
委曲颜常悦，
骞腾色愈恭。
会须陶谢手，
觅句细形容。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_433','予由中都还至暨阳道中闻禽鸣云明朝早起插田作诗识之','喻良能','宋','沟塍雨新足，
䆉稏秧正绿。
林间鸟声喧，
明朝起插田。
明朝插田起须蚤，
谢汝殷勤劝畦稻。
禽声禽声亦不恶，
大胜人歌金缕曲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_434','仆坐钓矶季野弟寄诗来因次韵','喻良能','宋','湖岸柳根半攲侧，
柳边仍有陂陀石。
不因斧凿成渔矶，
燕坐未妨钩饵垂。
磬湖宁待他山错，
白波分影涵翠幄。
翠幄阴中千结藤，
对面好山罗画屏。
遥岑无云明入眼，
遣我烂如岩下电。
平生不忧臭于铜，
俗氛安能蔽重重。
兴来散策饥来食，
起居无时惟其适。
诗穷吾师杜少陵，
一杯未用身后名。
他年挂冠不待老，
归来从君乞身早。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_435','以春盂送茂恭蒙以古诗为谢次韵奉酬','喻良能','宋','我家古瓮彭亨腹，
十年贮酒色如玉。
倾泻惟须老瓦盆，
精器便成蛇著足。
花瓷脆薄谁能携，
遣送君家保不亏。
虽然金碗未伯仲，
傥与椰樽相等夷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_436','勿言鲁酒薄为史端叔作也端叔同寮于越未终更求奉中都祠归丞相侍傍作是诗以送之','喻良能','宋','同寮虽云多，
交友未易结。
臭味一小异，
肝胆便楚越。
君侯宰相子，
风度何翩翩。
四偕计吏贡，
春铨复袖然。
一见盖为倾，
相逢岂在早。
白发与红颜，
论交非草草。
君才若杞梓，
真能世其家。
顾我如驽骀，
祇堪服盐车。
心情过中年，
何翅数日恶。
径须釂一樽，
勿言鲁酒薄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_437','天台歌','喻良能','宋','涉海神仙誇蓬莱，
登陆胜地称天台。
天台枕海连四明，
万峰千岭相萦回。
赤城绣出绮霞色，
瀑布界破瑶山青。
神仙居处寸步有，
游人白日迷杳冥。
剡溪昔年有二客，
五月此山同采摘。
只知采采不盈筐，
不觉行行失归陌。
龟肠蝉腹忽鸣饥，
倾壶进食欲令谁。
山桃一颗垂林畔，
共食歘然肌骨换。
下山得水涧石中，
以手饮之还濯盥。
又见芜菁出山腰，
一杯圆转中流漂。
二人相顾却相谓，
此地去人应不遥。
过溪水深四尺许，
又度一山逢二女。
韶颜艳色世所无，
南国东邻何足数。
笑唤刘晨阮肇名，
相识浑如旧有情。
问郎若个来何晚，
遂即殷勤相奉迎。
入户幔帷殊不恶，
错落珍珠与璎珞。
只将左右几青衣，
也胜人间誇绰约。
逡巡进脯饭胡麻，
琼杯片片斟流霞。
不知仙客来何处，
各把宫桃庆女家。
歌吹嘈嘈张内乐，
颜色有欢情有乐。
金鸦飞入向虞渊，
客散虚堂掩帘箔。
夜深各拥一仙娥，
泛泛鸳鸯在绿波。
和鸣乍自秦箫起，
行雨初从楚梦过。
瞥然一留因半载，
天气常如三月在。
百鸟哀鸣不可闻，
感此茫茫愁似海。
俗缘未断身未轻，
思归日有求归声。
更招女伴作离乐，
共写深衷无限诚。
曲终一出山中洞，
万里云烟空目送。
归来不见去时人，
寂寞惊魂若春梦。
子孙虽在不相知，
欲寻旧路已多歧。
棋迷柯岭难重见，
花失桃源空自悲。
风流云散令人惜，
至今犹唱阮郎归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_438','月山诸峰','喻良能','宋','平生固寡好，
嗜石如奇章。
家无千金产，
舁致穷涧冈。
寿星来金华，
衣冠何昂藏。
屈肘据膝坐，
风雨须眉苍。
松石产花溪，
奇诡颇异常。
鼻祖乃赤松，
素质侔白羊。
舞袖出烟霞，
浑脱类大娘。
想当虞韶成，
率兽杂凤跄。
觥觥石柱峰，
孤峭仍轩昂。
长不满五尺，
势欲摩穹苍。
狮子来何许，
俯首未腾骧。
何时一喷薄，
百兽走且僵。
鸱尾由天成，
略不假斧斨。
端宜侈绘事，
讵止工厌禳。
东坡小仇池，
大笔流芬芳。
康公醉道士，
名篇粲煌煌。
矧我此数峰，
价重百琳琅。
愿缔金石交，
出处永不忘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_439','月窗以所画观音见遗为赋一篇','喻良能','宋','白衣仙人云海上，
肉眼欲看唯想像。
月窗道人心孔开，
貌得人天行道相。
吾闻伯时晚画佛，
妙处不减王摩诘。
龙眠久矣寂无人，
安得却有伯时笔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_440','木状元惠示近诗一卷作诗为谢','喻良能','宋','洪都通守词华溢，
汉殿文章元第一。
万卷落落蟠胸中，
三江衮衮悬吟笔。
赠我玉佩联玦环，
未数大鹏兼小山。
欲知风味不能尽，
此卷长留天地间。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_441','王丞相生辰','喻良能','宋','皇宋十一叶，
时清风俗淳。
实维元首明，
亦繄股肱纯。
煌煌冀国公，
自昔抱经纶。
初掌黄麻诰，
黼黻同卿云。
继处宥密地，
五兵驱精神。
一品坐黄扉，
十载转洪钧。
雍容陪都俞，
黾勉承华勋。
镜净沧海波，
烟销紫塞尘。
伊傅堪并驱，
萧曹真下陈。
柔兆岁若午，
协洽寅在辰。
入梦一玉燕，
持炉两天人。
二十四书考，
八千岁为春。
西湖为酒醴，
南屏为膳珍。
万口均一词，
共祝柱石臣。
一祝锡难老，
再祝长同寅。
百祝配辽鹤，
千祝如大椿。
国寿箕翼齐，
洎公永无垠。
贵名与鸿烈，
日新日日新。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_442','王丞相生辰','喻良能','宋','金华千仞摩穹苍，
双溪迢迢碧流长。
清淑之气从风翔，
霜缣雾縠不足当。
真贤挺生金玉相，
上撷屈艳薰班香。
畴昔视草居明光，
鸿文大册压常杨。
既升紫枢兵气扬，
运筹决胜如子房。
鸿钧一气转混茫，
相吉崇璟何足方。
直与夔龙为雁行，
烟火万里俱耕桑。
冠带百蛮走梯航，
玉皇案前勤赞襄。
坐令我宋如虞唐，
中书事业殊未央。
二十四考嗤汾阳，
北堂西母寿而康。
荣封大国富井疆，
锦衣命服粲煌煌。
麻姑一半鬓未霜，
亭亭玉树阶兰芳。
徽献凝操书道昌，
向来王谢今祇王。
十倍江左浩莫量，
四海同词祝寿觞。
愿公寿比赤松强，
永作一柱扶明堂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_443','王枢使生辰','喻良能','宋','金华千古赤松宅，
中有初平叱羊石。
双溪衮衮泻苍波，
三洞潭潭接天碧。
钟英孕粹昴星精，
文章蚤岁瑞王廷。
横飞直上九万里，
红颜两鬓何青青。
金銮畴昔挥毫处，
尝草尺书招赞普。
职亲孰听玉宸钟，
夜分更秉金莲炬。
只今右府冠枢衡，
坐运精神驱五兵。
一烽莫睹狼烟燧，
四海不闻金革声。
苍生颙颙待霖雨，
黄屋便蕃颁异数。
姓名久已覆金瓯，
东街行筑沙堤路。
江左夷吾望更尊，
二十四考何足论。
已见威棱动蛮貊，
会看勋业照乾坤。
六十门生焚蕙炷，
再拜祝公如卫武。
柱石皇家不计年，
长容矿质入陶甄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_444','丙午仲春西湖舟中作','喻良能','宋','春阴将近一百六，
絮擘晴云新雨足。
烟边芳草碧如茵，
篱畔海棠红映肉。
相携逗晓出城西，
城西风景如杜曲。
两岸云光罨画浓，
一湖春水蒲萄绿。
坐中豪俊杂吴蜀，
磊落群书纷拄腹。
掀髯一笑浪波间，
淋漓衣袂寻棋局。
他年想像此风流，
应作生绡图一幅。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_445','东归','喻良能','宋','无边春意正冲融，
十幅归帆到浙东。
照水杏花红剪剪，
弄晴杨柳绿茸茸。
风光并入吟毫里，
山色都归醉眼中。
说与林间子规道，
丁宁不必向东风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_446','古风一首奉送淳叟太博通守豫章','喻良能','宋','刘侯精神秋隼紧，
高论悬河倾不尽。
至尊动色嗟谔谔，
权倖切齿畏謇謇。
致君未觉贾谊疏，
济时尚嫌马周窘。
三年博士向见治，
万卷蟠胸一何敏。
歘然大起故乡思，
自请题舆佐旟隼。
笑指江城欲载驰，
轻弃斑列谁能挽。
羡君去骑日骎骎，
顾我朝行犹蠢蠢。
语离宁惮十觞连，
惜别不知双泪陨。
赠言见意乏珠玉，
作诗饯行少铅粉。
从今数日待君归，
握手修门未为晚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_447','古风一首谢张漕子温惠示诗卷','喻良能','宋','前辈久零落，
老成惊创见。
平生耻问津，
如今真北面。
胸中五色丝，
织此锦绣段。
见之心孔开，
照眼光烂烂。
我亦好吟咏，
忍饥说刍豢。
辛勤三十年，
功效无一线。
偶兹得大嚼，
味永不忍咽。
嘉惠讵敢忘，
仁风敬扬扇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_448','叶自强读书堂','喻良能','宋','退之宰阳山，
暇隙唯读书。
同年大雅姿，
文史以为娱。
治剧逾整暇，
日与竹素俱。
頫首翻汉晋，
高声诵唐虞。
不善吾所鉴，
善者吾所摹。
撑肠仍拄腹，
何翅五千馀。
似闻书带草，
已复生庭除。
愿言饱经济，
舒之弥八区。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_449','四月二十九日坐直庐读山谷效东坡作薄薄酒二章慨然有感追赋一首','喻良能','宋','薄薄酒，
胜独醒。
丑丑妇，
胜鳏茕。
笙歌鼎沸不须羡，
松风满耳自足听。
前遮后拥未必乐，
邀月对影堪娱情。
晚食有味可当肉，
衡宇无灾胜列屋。
鲁东门外听钟鼓，
齐宣堂下状觳觫。
何如巢林一枝，
饮河满腹。
水硙多至三十具，
胡椒满贮八百斛。
何如浊酒一杯，
弹琴一曲。
子平为富不如贫，
子方称贱能骄人。
高明之家鬼可瞰，
网射纳税官不嗔。
中山醇醪醉千日，
文君远山致消渴。
不如茆柴百钱可一斗，
荆钗白头长相守。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_450','由下梅至资福估卖官产','喻良能','宋','晓发下梅寺，
霁色浮垄麦。
崎岖白杨岸，
诘屈黄牛轭。
野芳吐丰茸，
山羽鸣格磔。
驱车复前途，
聊欲遍阡陌。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_451','石钟山','喻良能','宋','南北两石钟，
上下一水侧。
造物妙镕冶，
蜚廉巧撞击。
镗鞳仍噌吰，
歌钟与无射。
丰山吾焉知，
蒲牢尔何力。
咨余久愿游，
偶此事行役。
时秋风飕飕，
日暮水激激。
初如钧天鸣，
乍若金奏寂。
入耳粹而清，
洗心欣以怿。
怪奇有如此，
游览谁能测。
发端示来今，
注经人姓郦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_452','龙池寺','喻良能','宋','发轫资福山，
弭辔龙池寺。
杪春新雨足，
老红围稚翠。
溪流素縠寒，
山色青罗腻。
拄颊坐移晷，
此意谁能会。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_453','伏日陪府公侍御登四望亭分韵得四字','喻良能','宋','危亭压层城，
是中有佳致。
面面看江山，
水云自相媚。
使君暇日登，
火老金正稚。
杯盘莹无尘，
笑语清有味。
快风千里来，
暑气三舍避。
赋诗红莲幕，
煎茶白衣吏。
诙谐想割肉，
摇扇笑疼臂。
乐事古云少，
能并今有四。
兹游岘山同，
千古知姓字。
吾辈亦何为，
虽驽犹附骥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_454','再游东阳','喻良能','宋','十年不到还重来，
往事一梦真悠哉。
寻幽已访涵碧寺，
乘兴欲上吴宁台。
苍松怪石虽饱览，
黄钿拒霜犹未开。
白云西来入我念，
又驭两腋清风回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_455','华峰亭','喻良能','宋','华峰抱紫翠，
兹亭瞰清幽。
春林罗画屏，
新月吐玉钩。
宛如东屯居，
恍若南涧游。
信美吾亦乐，
特用慰淹留。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_456','吉老手刃凶人为母报仇诗以纪之','喻良能','宋','卧冰叱驭全忠孝，
王氏多贤今古同。
公乎孝行惊创见，
落落岂特汉晋风。
凶人夜半发丘陇，
敢尔残暴不畏公。
古来刃雠不共天，
痛贯肝膂何时穷。
刳心设祭久自许，
何况临机敢不武。
拔刀断贼血模糊，
袍笏雍容诣官府。
忍耻贪生真可羞，
退之谆谆言复雠。
请衣一击当报怨，
豫子犹能致嘉传。
如公壮志今已伸，
他日定为忠义臣。
行看气节动天子，
诏书一洗泉下耻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_457','同从兄季弟游香山追和东坡端午游诸寺韵','喻良能','宋','前车惟伯氏，
后乘载阿连。
相携青莲界，
共开白社筵。
黄梅雨初歇，
红榴花正妍。
净境聊莞尔，
妙兴真悠然。
偈言溢四方，
经卷馀五千。
长廊含清风，
古潭摇苍天。
幅巾既萧散，
青鞋亦轻便。
登临自晨曦，
谈笑穷暮烟。
衡宇开卷坐，
僧房借榻眠。
却忆苏州语，
喧静两皆禅。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_458','向伯章通判请赋画扇','喻良能','宋','晴天万顷浮烟水，
小艇鸣榔烟水里。
一声欸乃西风起，
满轮明月蓼花秋。
富贵于我真浮沤，
世间何事不悠悠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_459','安抚开府史丞相诞辰','喻良能','宋','一年好处橘初绿，
雨后秋容净如沐。
潭潭大府忠孝家，
黄堂正奏千秋曲。
挥毫落纸妙卿云，
千佛经中蚤致身。
横飞直上九万里，
金鱼玉带真天人。
筹边利国知谁似，
直节长才堪重寄。
手扶杲日照乾坤，
力转洪钧陶品汇。
櫜兜戟纛粲煌煌，
紫极联休衮绣光。
暂向闽都分帅阃，
再归天阙致时康。
鲰生才业等袜线，
昔辱甄收今论荐。
喜看太白应长庚，
乐颂燕公符玉燕。
旧闻庄叟说大椿，
八千为秋八千春。
愿将眉寿同长久，
永作王家柱石臣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_460','次王待制维舟弄水亭韵','喻良能','宋','万里浮江更绝湖，
扁舟东入霅川图。
莫言旧菊荒三径，
须信中流待一壶。
今日诗筒烦远寄，
昔年樽酒记相呼。
立朝大节人能说，
月在青天影自孤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_461','次韵王龟龄状元西湖赏梅','喻良能','宋','乘閒选胜真悠哉，
正见千树冰花开。
天寒日暮湖面净，
疏影著水清无埃。
杏桃畏寒不敢吐，
春榜占作群花魁。
广平无人何逊死，
睥睨欲赋嗟无才。
东嘉夫子一何妙，
笔端游戏成琼瑰。
繁英丽句斗清好，
不用白鹭双飞来。
要令奚囊出佳什，
故遣渔唱传清杯。
西湖处士骨虽槁，
一唤暗香风味回。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_462','次韵王龟龄侍御不欺室','喻良能','宋','与玄虽非童九龄，
向来亦既许攀鳞。
从容撰屦饱言论，
我知公直社稷臣。
此心炯炯贯白日，
何止不欺寻丈室。
霜台白简凛乘骢，
史馆诛奸森直笔。
紫岩先生子张子，
百世一人嗟已死。
室中八十四骊珠，
千载流芳同信史。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_463','次韵王侍郎寄题亦好园','喻良能','宋','磬湖鸥鹭自相亲，
湖边山园步步新。
鱼鸟细看自足乐，
芋栗可收犹未贫。
我觉有园贫亦好，
人笑此园何太小。
他年便拟当菟裘，
不羡莼鲈归计早。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_464','次韵王待制读东坡诗兼述韩欧之美一首','喻良能','宋','文章端与时高下，
列国有风周有雅。
建安气质混不伤，
齐梁纷纷堪斗量。
先唐诗人子韩子，
落笔洗空千古士。
篇章杼轴自己出，
正派犹能传六一。
作诗馀事真诗仙，
骑麟被发何翩然。
韵宽泛押入傍近，
窄韵宜搜期押尽。
钩章棘句未多郊，
古讽新题宁数稹。
五季诗流喜穿凿，
蝉噪蛙鸣嗟众作。
皇朝天人欧与苏，
星凤初见人惊呼。
醉翁句法到胜处，
纡馀条畅今古无。
铺张扬厉词藻挟，
雅称金泥兼玉检。
一篇妙绝庐山高，
几首清新写郁陶。
造化机缄富状汇，
岂独文星南斗避。
如何妄评味短长，
自古群儿喜嘲议。
雪堂羁穷如牧之，
得非天欲昌其诗。
平生古律三千首，
无愧清风白雪词。
才如太白更无敌，
文似子长兼爱奇。
江西宗派不足进，
自郐以下曾无讥。
流传海内皆珠玉，
到处逢人俱愿学。
不须酬唱说西昆，
宋有欧苏唐有韩。
二文邈乎其杖几，
一编且诵苏夫子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_465','次韵王待制游东坡留题十一绝','喻良能','宋','何处重寻饭颗诗，
先生诗语总英奇。
细吟出月穿天句，
想见挥毫落纸时。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_466','次韵巩宪见示桐柏瀑布之作','喻良能','宋','昔闻孙兴公，
尝赋飞流水。
至今福庭地，
犹属羽人里。
瀑泉天半来，
界道见清泚。
迢迢白虹贯，
隐隐玉龙起。
宇宙虽云宽，
壮观知能几。
谷帘信有之，
界图宁辨此。
清秋饶爽气，
朱夏绝埃滓。
何当振金策，
逍遥山之趾。
眺览既惬适，
啸歌何穷已。
青鞋未成往，
抚己空自鄙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_467','次韵伯寿兄残春即事','喻良能','宋','屏居事幽潜，
亲故成久别。
茅檐翳浓绿，
酴醾堕香雪。
山气清凉国，
溪声广长舌。
但须贤人酒，
安用长者辙。
吟肠绕碧云，
醉脸晕红缬。
奴耕谷可徯，
儿书笔难掣。
地偏尘不到，
心境两清绝。
啸歌何穷已，
未觉处身拙。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_468','次韵伯寿兄海棠','喻良能','宋','无情长笑杜陵老，
不识海棠春意好。
东坡作意赏东风，
为爱轻绡映肉红。
枝头点缀知多少，
贪睡今年开不早。
含情欲开还未开，
紫蝶黄蜂亦懒回。
可怜熟视明人目，
长恨年年看不足。
晓来风定雨霏霏，
减却春光一片飞。
多愁更被花相恼，
宁惜春衫同藉草。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_469','次韵何茂恭永新见寄之什','喻良能','宋','尺书将远意，
飘忽渡江湖。
嘉楮藤溪少，
纤毫月窟无。
封题烦妙札，
沾丐到迂儒。
多谢相思切，
迢迢千里途。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_470','次韵何茂恭咏玉簪三绝','喻良能','宋','月露洗沐秋容净，
姑山初逢冰雪仙。
风流水部与藻饰，
从此梅花应并传。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_471','次韵杨廷秀浣花图歌','喻良能','宋','诗翁衔袖出清诗，
醉墨淋漓惊乍写。
明珠炯炯照户牖，
恍疑骊龙睡遗者。
弥明高唱诗云云，
此翁一扫如飞蚊。
诗狂克念酒作圣，
樽前笑杀刘师命。
李白张旭称世贤，
姓名优入少陵编。
平生我亦忝词客，
自得此诗轻尺璧，
他年别去长相忆。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_472','次韵侍御五月二十日闵雨','喻良能','宋','使君慕丘祷，
用志端不分。
天高听甚卑，
深知使君勤。
立致楚东雨，
如开衡岳云。
赖此苗尽活，
不然尪可焚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_473','次韵周敏卿秋兴三首','喻良能','宋','悠悠草根虫，
鸣声近我床。
皎皎林间月，
亦已照我墙。
感此动万虑，
聊复举一觞。
何以侑我酒，
清啸闻疏篁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_474','次韵周敏卿秋兴三首','喻良能','宋','团团岩中桂，
移根篱舍间。
秋风一披拂，
袅袅天香寒。
对此径须饮，
把酒酬西山。
浩歌何穷已，
宁必素与蛮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_475','次韵周敏卿秋兴三首','喻良能','宋','炎暑堕何许，
凉风忽吹衣。
野水映荒岸，
寒丛秀疏篱。
萧萧林影薄，
杳杳鸿声悲。
秋禾亦既穫，
聊足充吾饥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_476','次韵奉酬刑部王嘉叟侍郎书戏䌽集后','喻良能','宋','制作参易经，
不用草玄准。
眼空天壤间，
谁得并捷敏。
鸿文翻水就，
未省苦吟吻。
齐梁逮陈隋，
众作付一哂。
南国容本冶，
西子发更鬒。
混然真天成，
宁复分域畛。
飞上青云端，
秋空击鹰隼。
岂唯持荷橐，
已复班玉笋。
虽未究所长，
要亦摅素蕴。
大手秉纶綍，
至音发簴簨。
嗟予堕诗穷，
政坐无铅粉。
数奇祇自怜，
多忤谁汲引。
有赋难逐贫，
无诗不招隐。
明公独深怜，
不嫌边幅窘。
谓虽敝帚如，
或可充贡箘。
恃此以无恐，
枚皋穷久忍。
傥复念菅蒯，
庶免辱荆槿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_477','次韵奉酬赵景明法曹见赠','喻良能','宋','宗英贺白俦，
肯从野人游。
相见各失喜，
胡为俱皇州。
孤灯照清谈，
新诗澹牢愁。
明日却分袂，
独往涛江头。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_478','次韵宗郎中师仁见示古风','喻良能','宋','平生癖于诗，
业债馀清净。
但已心孔开，
敢誇笔锋劲。
疾书或攲斜，
所向必雅正。
顾惭非晋人，
出语那韵胜。
亦好三亩园，
松竹互掩映。
门阑虽间启，
俗客未省迎。
岂唯惬幽情，
颇复动诗兴。
朅来古泮宫，
未谙麋鹿性。
何处更有诗，
抗走足不定。
宗英出大篇，
重此绿绮赠。
未应费推敲，
讵止工竞病。
此作不为妙，
妙处知难更。
吟坛将风雅，
琐尾宜退听。
贺白真雁行，
离骚可奴命。
熟复句中眼，
如对麈尾柄。
迷途获指南，
从此识畦径。
自应形赞叹，
谁复献嘲评。
佳处未易知，
当有识者證。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_479','次韵林明府何主簿唱酬之什','喻良能','宋','向来十载愿识韩，
一日下车许追攀。
美句已出黄初右，
清谈尚馀正始间。
烦公笔底澜翻水，
洗我胸中磊磈山。
更挽何郎入诗社，
三人俱有䌽衣斑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_480','次韵茂恭见寄','喻良能','宋','中书一挥千万言，
有如水悬吕梁间。
奔逸绝尘不可及，
蹇欲从之良独难。
如君文字可华国，
胡为犹在南湖侧。
樊川昌谷纵多才，
欲以比君那可得。
君家红杏连白榆，
似向君王得鉴湖。
水光溶溶浸山色，
楼台上下如冰壶。
磬湖萧瑟逢秋令，
男呻女吟贫非病。
阿奴碌碌仅自全，
伯氏今亡嗟短命。
恨我不如大小山，
徒尔思苦仍辞艰。
既无击钵挥毫敏，
空愧诗筒数往还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_481','次韵郑季远国录贤良题余庐山诗记','喻良能','宋','天姥梦魂劳太白，
赤城想像赋兴公。
匡庐缥缈烟云境，
总在新篇妙句中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_482','次韵逢使君寺丞见赠','喻良能','宋','冰花零乱飞庭户，
夜色晶莹似三五。
诗仙晓赠白雪篇，
便觉清风追吉甫。
区区五斗不知疲，
故园应有北山移。
冻冷不暇搜佳句，
千里归心到乡树。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_483','次韵提举王正言寒食游茶焙','喻良能','宋','摘山胜煮海，
财货所源流。
建焙甲天下，
赋入十倍收。
国计颇赖之，
贡输何时休。
择人为提领，
得贤从宛丘。
文章脱吏腕，
风味登瀛洲。
佐职亦已久，
再见春草抽。
郊原富枪旗，
岁事日以修。
抚民端若子，
疾恶信如雠。
驱车向凤山，
父老观道周。
青春行画图，
佳处时一留。
风前耳潺湲，
雨后目纤柔。
酒酣已胜赏，
珠唾挥钓钩。
咨予素么么，
受恩犹未酬。
铭心虽甚坚，
抚己徒怀羞。
平生困坎壈，
暮年尚依刘。
投公一纸书，
远寄粤王州。
书传得妙帖，
想像寒食游。
终防好事人，
豪夺或巧偷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_484','汲水','喻良能','宋','山泉盈石坎，
抱瓮每相从。
不敢伤蝌蚪，
疑能化小龙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_485','约季野九日登云黄不果季野有诗因次韵','喻良能','宋','青山如候虫，
可赏不可恋。
胡为谢康乐，
游览乃欲遍。
纵登最高顶，
过眼犹掣电。
何如菊花天，
周绕篱落畔。
对面黄云峰，
未妨篱下见。
相携凌紫霞，
更约东风便。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_486','观田家宴集','喻良能','宋','村落秋气高，
凉飙泛林莽。
田家刈穫閒，
斗酒劳良苦。
瓮瓯间竹箸，
杀鸡仍具黍。
昏昏灯火照，
草草杯盘举。
初喧鹅雁声，
中静儿女语。
醉来或田歌，
散去亦社舞。
不信五侯家，
软盘荐肥羜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_487','过分水岭初出建宁界','喻良能','宋','辛卯踰闽峤，
淳熙出建关。
㳽漫第五渡，
险绝百重山。
近夏凉风发，
新晴丽景还。
翠烟飞缥缈，
好鸟语绵蛮。
密树青罗幄，
连峰碧玉环。
野英纷剨剨，
岩溜碎潺潺。
小艇横清泚，
飞桥截碧湾。
机舂流水激，
架厂石崖悭。
紫笋和泥采，
青梅带叶攀。
未能供旨味，
聊得悦慈颜。
取醉三杯适，
攲眠一饷閒。
自怜霜鬓白，
人羡䌽衣斑。
物色挥毫里，
家山隐几间。
狂歌聊尔耳，
同志傥吾删。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_488','齐山','喻良能','宋','龛岩宜号秘密藏，
翠微应呼清净身。
欲凭妙句发佳境，
安得挥毫我辈人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_489','伯琬明府年兄和予致字韵诗举英石见遗谨次来韵以报盛贶','喻良能','宋','久闻英石空流涎，
意欲得之无力致。
士衡东头富玲珑，
染指独许尝鼎味。
明窗净几拂蛛尘，
尤物定自能移人。
报惠惭无百金寿，
赠公相好无时朽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_490','伯琬明府年兄和予致字韵诗举英石见遗谨次来韵以报盛贶','喻良能','宋','公家一峰如终南，
须信是中有佳致。
对之忘饥亦忘愁，
岂待声色兼臭味。
嗜好萧然迥出尘，
同年要是我辈人。
世间何物如石寿，
墨妙与之俱不朽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_491','何司业和屋字诗见诒次韵奉酬','喻良能','宋','亦好园林富松竹，
爱山堂上书连屋。
恨无妙语为题品，
空对奇峰有十六。
先生佳句落泉石，
杜诗韩笔端能续。
有如妙响发朱弦，
恰似清音动寒玉。
须知小圃辱提撕，
何异寒门被收录。
从今草木有光辉，
盎盎春温入邹谷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_492','何茂宏茂恭携酒见过复侑以诗次韵一首','喻良能','宋','薄云漏朝曦，
积雨霁中夏。
白波涵磬湖，
清影漾茆舍。
轮蹄绝还往，
文史富閒暇。
畏友有机云，
英标凛王谢。
喜寻范张约，
偕命嵇吕驾。
岂徒贵密迩，
聊亦重姻娅。
戏彩膝才容，
亦好草可藉。
瓦碗荐溪毛，
竹箸羞鸡炙。
剧谈掌屡抵，
粝食咽亦下。
晚凉过古刹，
明月耀脩架。
蒲团语上方，
篝火耿良夜。
凌晨一瘦藤，
支径双不借。
长啸陟云岭，
清吟探石罅。
嵚岑近明目，
湍激深没胯。
别袂余力掺，
归鞍子佣跨。
何时许重临，
倒屣肃邀迓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_493','余同年由试院积俸给买马而归中路几逸戏作长句赠之','喻良能','宋','知君几作东野毕，
瘦马田间风欲逸。
圉人白汗似翻珠，
暂尔奔腾未为失。
归家须办紫游缰，
玉辔红缨摇闹装。
一鞭嘶风映垂杨，
要试宁川春草长。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_494','余祷雨龙湫翼日响应儿子兴之有诗纪实仲文季直弟亦既同赋老子久不作诗因得绝句','喻良能','宋','龟龄昔祷五龙庙，
曰雨而雨若有期。
我无能为此云役，
云螭何事不相违。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_495','园中口占','喻良能','宋','舂锄野凫疑水乡，
湖阴山色仍苍苍。
西风三径有佳致，
朔雪横枝多暗香。
长统游戏自足乐，
少游赢馀非所望。
开林贴石兴未已，
瓜时逼人须趣装。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_496','寿星泉','喻良能','宋','水边岂无清江使，
石上自有黄冠仙。
更须唤取辽东鹤，
便是人间不老泉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_497','张丽华','喻良能','宋','张家女儿号丽华，
十岁选入君王家。
君王一见念玉雪，
唤作后庭琼树花。
临风结绮香风度，
自谓朝朝兼暮暮。
那知梦断金井栏，
往事茫茫堕烟雾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_498','张持荷示诗编次韵一篇为谢','喻良能','宋','先唐诗道昌，
万象绕吟笔。
长吉穷崄怪，
奚囊销永日。
一洗齐梁陋，
古澹见摩诘。
诘斋妙入神，
二者无一失。
游戏唾成珠，
所至动盈帙。
长篇杂短咏，
朱弦响玉律。
脱身声利场，
宴坐心更逸。
高眠听松声，
清话剥芡实。
声名笑山王，
任达景嵇毕。
时发孤凤鸣，
不作寒蛩唧。
人讥雕肺肝，
悠然非所恤。
编成客未佳，
椟藏谨勿出。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_499','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','苏公亦有言，
公合把旌旄。
庶使湛辈名，
亦与岘山高。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_500','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','大雅久不作，
淳风日浇漓。
挽回既狂澜，
此道非公谁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_501','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','文章无正体，
源浚流乃深。
能者主宰之，
古来非独今。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_502','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','直道盖中朝，
雄名横六合。
吾道其非邪，
胡为未舟楫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_503','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','作诗必坡老，
作文必欧公。
欲知鸣道心，
端与二公同。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_504','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','退之在元和，
昌言主文字。
扬镳踵芳尘，
公乎得无意。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_505','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','三赋成会稽，
四集始东楚。
一洗凡马空，
斯文有宗主。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_506','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','不见我公久，
摇摇动心旌。
敢以一瓣香，
为公罄精诚。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_507','怀东嘉先生因诵老坡今谁主文字公合把旌旄作十小诗奉寄','喻良能','宋','对策婉而切，
奏疏忠且纯。
风行水自波，
至哉天下文。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_508','李侍郎三和屋字诗次韵为谢','喻良能','宋','卫武文章比淇竹，
闭阁著书欣仰屋。
胸蟠载籍馀万卷，
为家五百九十六。
词华尔雅骚可奴，
议论渊源经可续。
笔端凛凛挟风霜，
齿颊泠泠漱冰玉。
久知广大端可法，
自顾么微何足录。
愿同湛辈附羊公，
庶比江西派山谷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_509','村居夜坐读王右丞山中与裴迪书爱其清婉有魏晋风味因集其语作诗一首亦老坡哨遍之义也','喻良能','宋','景气既和畅，
故园殊可依。
远山映清月，
曲水涵沦漪。
寒犬吠如豹，
村舂闻自机。
因思曩昔友，
携手同赋诗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_510','近结茅屋数椽以可赋轩揭取子美可以赋新诗之义用沈约体赋诗一首','喻良能','宋','安仁偃息处，
之问读书室。
茅轩规昔人，
聊可容吾膝。
幽芳秀垣曲，
翠筱蓊檐隙。
松窗炯虚明，
荆篱互疏密。
淡月晓窥几，
候虫夕鸣壁。
诗书后前陈，
图史左右秩。
遐览到三五，
旁搜及坚白。
一语偶有得，
寸心欣自适。
轮奂非所慕，
兹焉颇放逸。
渊明傥来过，
真趣会能识。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_511','闳中堂','喻良能','宋','危檐覆虚明，
景趣清且长。
曲池散涟漪，
珍木含葱苍。
离离荔子丹，
冉冉茉莉香。
有堂既足佳，
无毡庸何伤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_512','饮饯王共父分韵得转字','喻良能','宋','子猷风味最诸王，
墨妙文工眼如电。
惯吟疏雨滴梧桐，
解道澄江净如练。
去年落笔中书堂，
姓名高彻蓬莱殿。
至尊动色催除目，
俾向兰台参俊彦。
要成远业待时须，
故遣读书破万卷。
夫何归思动岷峨，
自请题舆近乡县。
学省诸公怅别离，
击鲜载酒开芳燕。
欲浇胸次数日恶，
剩作林亭百壶饯。
落花送酒舞缤纷，
乱絮催诗飞眩转。
临歧那用赋销魂，
但要修门重会面。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_513','侍御王公去饶饶之士民数千万人遮道攀辕又相与断城北桥以留之公不得已乃回城从间道遁去馀干主簿翁君画断桥图作诗二十韵寄侍御求和侍御以和篇见示因次韵一首','喻良能','宋','东嘉老先生，
文字继坡谷。
治饶如京兆，
三王岂其族。
政成无一事，
澹若处幽独。
追踪古循吏，
清净非碌碌。
每以坐啸馀，
时出阳春曲。
风流化邦人，
吟咏成国俗。
乙酉秋七月，
天地正炎燠。
有诏帅夔门，
引道不淹宿。
境内闻公行，
仓皇守牙纛。
攀辕人填咽，
遮道车击毂。
已去复挽回，
出入成重复。
桥断蜂腰分，
巷拥鱼鳞矗。
竟从间道去，
复许谁追逐。
子母若弟昆，
相顾皆嚬蹙。
吾父既往矣，
畴能继英躅。
孟尝附商船，
千古垂简牍。
偷席广文毡，
使者为标目。
去思闻九重，
盛事传西蜀。
先生美无度，
推诚置人腹。
画图照人间，
斯民记恩育。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_514','侍御宴僚属于番江楼以卧病不克与分韵得四字','喻良能','宋','使君自是廊庙器，
五马一麾聊尔耳。
今年清净狱既空，
去岁丰登米不贵。
郡中九贤政可十，
京兆三王何足四。
乘閒领客宴江阁，
对景题诗忘肉味。
坐间僚属总文采，
笔下波澜更源委。
夏木阴阴啼鸟喧，
烟波渺渺轻帆驶。
错落觥筹略达尊，
从容笑语穷幽意。
嗟予薄命捩翻羹，
卧病空斋吟拥鼻。
画戟凝香不同赋，
白衣送酒犹沾醉。
追攀逸韵苦无才，
想像清欢欲生翅。
兰亭被罚定非佳，
金谷望尘吁可愧。
他年江左仰遗风，
应有画图传盛事。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_515','参议李郎中惠示古律诗两巨轴次韵首篇奉酬','喻良能','宋','邺中七雄迹既扫，
谢楼梦断池塘草。
仙李诗人麻竹多，
佳句唯传杜陵老。
省郎句法专后来，
压尽今世诗流才。
并刀剪水有佳致，
月中聚雪无纤埃。
穿天出月馀四纪，
捉月风流今不死。
从教人售一杯水，
自信笔挟风霜字。
次山风味唤仍回，
老文犹未磨苍崖。
收拾明珠百馀斛，
寒光入夜阖复开。
我得公诗兴叹慨，
千古长留诗卷在。
祇恐天官下取将，
人间古货今崖卖。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_516','参议林郎中蓄乘轩君向来止有其一今日见之乃有嘉偶因得小诗','喻良能','宋','物情非耦不能久，
并蒂芙蓉亦自双。
珍重鹤君新得配，
故应清唳彻秋江。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_517','周希稷见示诗卷作诗为谢','喻良能','宋','周郎列宿胸中罗，
笔端有口如悬河。
赠我明珠六十八，
一一照乘圆无颇。
我学谷梁失也短，
君才士衡患其多。
中兴功业要纪述，
浯溪石崖当往磨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_518','咏怀','喻良能','宋','一夔方佐舜，
二公还相周。
三杰从高祖，
四皓屈留侯。
五龙翔日边，
六逸啸溪头。
七贤傲竹林，
八仙隐糟丘。
九老山中卧，
十友方外游。
百鍊竟不变，
千载存风流。
名节良足贵，
万事真悠悠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_519','夜宿天章寺','喻良能','宋','兰亭负崇冈，
脩竹翳寒绿。
嚣烦隔人境，
爽气森佛屋。
薄暮行役罢，
言就上方宿。
是时秋峥嵘，
西风响岩谷。
越兰不可见，
浩歌想馀馥。
右军恨何许，
禊序空三复。
夜久百虫绝，
灯花媚幽独。
萧然四壁静，
一洗尘万斛。
何当脱羁鞅，
阴岩事卜筑。
聊复得此游，
澹然心赏足。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_520','庚戌中秋病起言怀','喻良能','宋','病来十日不饮酒，
起对中秋良可人。
银汉迢迢清未了，
金波潋潋净无尘。
艳歌未暇成三叠，
美酝何妨釂十分。
记得昔年当此景，
厌厌夜饮在成均。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_521','武夷山','喻良能','宋','冲佑观前水绀色，
升真洞北山笋攒。
群峰不断四时翠，
万壑长留九月寒。
溪上桃花引渔子，
云间仙犬逐刘安。
平生饱识佳山水，
直作东南第一看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_522','直庐锁宿呈监丞宋丈','喻良能','宋','轩窗空洞惟脩竹，
风韵时时自琴筑。
学省萧然冷欲冰，
两翁相对清如玉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_523','若耶曲','喻良能','宋','若耶溪上凉如许，
五月清风不知暑。
半空浓翠接苍烟，
满眼轻阴觉疏雨。
织女潭边深复深，
绕门山畔石成林。
红妆荡桨谁家女，
笑入荷花无处寻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_524','苦热不寐独起对月','喻良能','宋','暑气推不去，
凉风挽不来。
中庭月色净，
揽衣起徘徊。
夜久万籁寂，
秋近孤蛩哀。
月堕玉绳低，
此兴真悠哉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_525','试院一首','喻良能','宋','南国诸侯老宾客，
霜叶青衫头雪白。
绣衣使者急搜贤，
又向文场三捧檄。
全闽多士如邓林，
大厦度材惭匠石。
细看太白日万言，
时取武成二三策。
清心期识璞三献，
过眼敢迷目五色。
只今虽无衣钵传，
向来未省原天觅。
更长宁辞烛屡秉，
漏下何啻夜十刻。
回思前日踏槐花，
忍使青袍轻饮墨。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_526','雨后晓行','喻良能','宋','宿雨晓初收，
长天澹如洗。
解带临清流，
泉声细娱耳。
有如到愚溪，
还似游栗里。
人生若此少，
贫贱非所耻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_527','星源县斋书事','喻良能','宋','冬仲弭征辔，
歘焉及新春。
饱吃番阳饭，
细治星源民。
星源故自佳，
民俗良易驯。
不嫌聋丞愚，
翻爱假令真。
相与不忍欺，
见谓无缁磷。
牒讼日以简，
赋输日以臻。
遗我以暇隙，
使得窥典坟。
短檠一窗灯，
孤讽至夜分。
平明坐厅事，
帘影清无尘。
闾里颇熙熙，
孰云民不淳。
顾谓汝父老，
辱爱亦已勤。
为我理归棹，
吾久思吾亲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_528','春兴','喻良能','宋','日日春泥妨杖藜，
一声何处子规啼。
红将满地花空委，
绿尽前山草正萋。
已办篇章书侧理，
可无杯斝捧柔荑。
清明过后芳菲少，
桃李清阴欲满蹊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_529','春晚遣兴','喻良能','宋','乳鸭池塘春水满，
秋千院落东风暖。
帘间燕子语虽忙，
叶底黄鹂啼更缓。
长大何如年少时，
雕鞍骏马踏芳菲。
闭门不觉庭花落，
颠倒残红作地衣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_530','显谟左司周公元吉将漕湖北一时名流赋诗饯行予与左司同出于詹事周公之门为同门同居班列二年为同朝同考类试于贡闱为同寮三者既同契好弥笃于其行也作长句以送之','喻良能','宋','微云疏雨凉新秋，
皇皇玉节掺不留。
夫君不惮原隰险，
圣主坐宽宵旰忧。
巴音聊复祖行色，
楚水恨不尾仙舟。
籍籍预传新漕挽，
汗青未数富民侯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_531','点检朝陵内人顿递至西兴道中纪事','喻良能','宋','平湖潋滟摇春风，
扁舟轻驶如飞鸿。
垂杨万缕长青茸，
倚岸崇桃醉脸红。
满空烟雨霏濛濛，
柯桥精庐闻午钟。
平畴麦苗青芃芃，
崇峰秀岑纷玲珑。
图经未看名叵穷，
雨葩烟叶交朦胧。
吾欲图之谁其工，
妙语却思六一翁。
解道山色有无中，
薄暮舣舟依竹丛。
夜深点滴听孤篷，
天明利涉浮梁雄。
钱清虽小炊烟重，
我生之辰今适逢。
一杯不暇缘匆匆，
聊以新诗娱老悰。
龛山西北水溶溶，
白鹤桥边小梵宫。
海天茫茫空复空，
放眸一望日本东。
萧山小邑河阳同，
桃李漫山如锦幪。
溪旁驿亭名梦笔，
故居知是江文通。
西兴浦口天连水，
满眼长安紫翠浓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_532','独善堂','喻良能','宋','赏心并四者，
文史足三馀。
不作簪绅念，
唯便水竹居。
佳名元籍籍，
真乐每如如。
月旦遗评在，
今经几建除。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_533','狱空','喻良能','宋','公庭日将夕，
吏报空狱岸。
虽无春草鞠，
已有蛛丝蔓。
欢乐见鸟乌，
呻吟绝鹅雁。
谅非片言折，
聊发一笑粲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_534','砚屏','喻良能','宋','长江远浪连天碧，
岸柳垂垂临断石。
渔舟一叶白头翁，
独把钓丝待鱼食。
我身犹是红尘客，
对此无言三叹息。
安得轮竿入手来，
与君共钓消长日。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_535','秋晓野步','喻良能','宋','幽居迩郊原，
出户目已瞭。
閒携一枝竹，
散步及秋晓。
寒烟引轻云，
澹澹萦木杪。
矫首瞩层穹，
转盼失飞鸟。
野潦净荒陂，
惊飙泛枯筱。
世态徒营营，
此心殊了了。
佳处谁与论，
聊用付清醥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_536','秋暑炽甚忍饥偶作书季直弟以诗见嘲因次韵','喻良能','宋','老夏雨既少，
稚秋云亦无。
枯池罢桔槔，
蔫花委芙蕖。
不糁漫藜藿，
不爨空樵苏。
苏州亦有言，
家人笑著书。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_537','种菊','喻良能','宋','子猷借宅亦种竹，
渊明荒径犹存菊。
九日黄英凛碎金，
三冬翠干森寒玉。
亦好才围一亩宽，
恨无九畹养芳兰。
聊种寒花一百本，
要伴此君秋后看。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_538','追和陈子高赠王法曹韵','喻良能','宋','肯学少陵对马军，
肯同太白谢汪伦。
聊将文字饮一盏，
不待月影成三人。
门前车马闹迟日，
陌上绮罗娇暮春。
想见流觞多乐事，
酒酣人问斗升嗔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_539','送王节推夷仲秩满赴阙','喻良能','宋','战和未定议纷纭，
草茅有忠天莫闻。
公乎行矣陪国论，
毋愧新亭千载人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_540','送王节推夷仲秩满赴阙','喻良能','宋','胸中深蟠万卷馀，
笔端倒倾蛟室珠。
掖垣政要舍人样，
致主泽民推宿儒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_541','送刘孟冶司令之官四明','喻良能','宋','先生行孝人莫攀，
平生急禄怡亲颜。
三千曲礼发已白，
七十老莱衣尚斑。
秋容新沐江涵天，
潘舆低昂御花间。
凭谁为唤吴道子，
一写画图连越山。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_542','送吕宪帅维扬','喻良能','宋','读我宋实录，
元丰治明昌。
五年九月中，
上特开天章。
从容谓辅臣，
边民疲可伤。
吕独为朕言，
他人终未尝。
已乃命正献，
由定帅维扬。
学士加大称，
庸以示宠光。
移镇未去久，
趣归总台纲。
尔来九十年，
谁其踵遗芳。
我公嫡孙行，
祖烈蔚载扬。
持节古闽粤，
摄事今福唐。
仁风杂和气，
盎盎如春阳。
氓谣玉律响，
圜扉春草长。
英声飞九重，
御屏书益详。
广陵大都会，
经理须才良。
拥麾往镇之，
非公谅谁当。
延阁升宝书，
恩纶湛洋洋。
左符分淮海，
西顾宽岩廊。
想见入境初，
快睹争星凰。
折冲向樽俎，
宣威谢金汤。
行看有锋召，
衮衣侍虞皇。
贱子一何幸，
窃庇逾两霜。
误蒙剡荐牍，
名彻凝旒傍。
受恩未知报，
肝胆徒激昂。
唯祈转洪钧，
复立弟子行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_543','送杨飞卿国录','喻良能','宋','杨侯作录来成均，
野鹤昂昂端不群。
一朝议论不入意，
弃掷禄位如浮云。
群公挽衣留不住，
直入苕霅亲耕耘。
惜吾无力叫帝阍，
不能以侯直谅闻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_544','送参议李器之','喻良能','宋','人间今北海，
天上谪仙人。
雄论堪医国，
新诗可泣神。
摇毫云落纸，
挥麈坐生春。
芸阁登吟惯，
绫衾入直频。
三十辞故里，
二载宦全闽。
婉画裨南阃，
英名动北辰。
惠风吹别思，
细草碾征轮。
行矣跻华要，
声猷日日新。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_1_545','送参议林郎中','喻良能','宋','人孰不识面，
相知贵知心。
唯我与夫子，
倾盖成断金。
畴昔居京邑，
庀职偶相临。
肯纡钟期聪，
俯听牙弦琴。
讲说三百篇，
一一蒙赏音。
朅来钟山旁，
休沐同搜吟。
联镳照湖侧，
携手天衣岑。
飞鸣互嘤嘤，
和乐长愔愔。
无诗不属和，
有酒相与斟。
饷我破羌帖，
佳妙同来禽。
复遗先圣像，
摹写自孔林。
二年如巨蛩，
一旦辰与参。
襟期自兹远，
诗盟几时寻。
愿言蚤盍簪，
无为徒滞淫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_546','送洪右史赴召三首','喻良能','宋','月宿南斗穷何遣，
爬沙脚手钝可咍。
一生冰清但糠秕，
两鬓雪白独尘埃。
达人疑剑未免按，
夷途荐毂谁当推。
公乎行矣断国论，
能忘料理忍穷枚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_547','送洪右史赴召三首','喻良能','宋','长公前日辞揆涂，
少公今日被锋车。
路人共指拜内相，
天子久欲登鸿儒。
黄麻端拟似经训，
金莲不独荣传呼。
如闻书诏正填委，
北辕疾驱公勿徐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_548','送洪右史赴召三首','喻良能','宋','胸蟠补衮五色丝，
笔驱波涛三峡词。
上追班马真辈行，
下视燕许如儿嬉。
拙工废绳那足道，
巧匠缩手今当施。
前途著鞭政须急，
玉堂独步非公谁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_549','送晏伯安','喻良能','宋','古绸于今婺，
盖亦一壮县。
剧繁号难理，
百令无一健。
英英晏伯安，
年壮政则练。
咄嗟扫宿弊，
谈笑了宿案。
公庭坐无事，
自可名道院。
老眼空四海，
于公惊创见。
今公赋归欤，
敢以一语饯。
边陲正驿骚，
朝野未閒燕。
公才浩纵横，
敌可受八面。
要须诣明光，
上书还自荐。
口伐或箸筹，
收功在不战。
不然飞刍粟，
坐使军储羡。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_550','送高炳如倅天台','喻良能','宋','高侯吾所畏，
学问觑壶奥。
秋水莹精神，
春华丽词藻。
三馆朅来游，
两鬓青未皓。
何心玩岁月，
刻意事探讨。
二志既崇成，
八书可偕考。
乌台伫风采，
纶闱须典诰。
引疾遽有祈，
勇退一何早。
丹丘非大名，
泥轼仅小好。
会看有诏追，
岂必俟身到。
行矣即轻安，
恺悌神所劳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_551','重九会饮爱山堂','喻良能','宋','閒居爱重九，
赊酒对黄花。
水榭杯盘莹，
家人笑语哗。
宦情薄秋霭，
吟思绕晴霞。
向晚归途好，
飘飘醉帽斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_552','重阳','喻良能','宋','一年秋节重阳浓，
园林上下皆清风。
远山百里削寒玉，
平湖十亩磨青铜。
亦好茂树蓊西北，
露枝霜叶纷青红。
枝头寂寂少啼鸟，
天外隐隐飞征鸿。
弄月基蟠绿净中，
东南况有小垂虹。
潭清潦尽境更好，
水落石出摹难工。
爱山堂前花作丛，
疏疏杨柳瘦毛同。
红蕉碧桂互掩映，
芦花蓼穟交蒙茸。
新亭爽垲瞰空阔，
赁栏一目连七峰。
烟霏雾霭扫欲尽，
但见突兀撑晴空。
携筇更登月山椒，
嶙峋怪石高玲珑。
香炉近出陂陁侧，
云黄复在南山东。
水声激激来涧曲，
飕飕风响生樛松。
菊英萸实篱可采，
山肴野蔌盘能供。
作诗颇类台戏马，
吹帽未减山名龙。
良辰美景乐心赏，
四者偶并今始逢。
明朝不问蝶愁绝，
更饮黄花琥珀醲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_553','斋宿昭庆院祀南岳南海','喻良能','宋','秉檄奉中祀，
驱车出重关。
晓风铁叶岭，
烟雨南屏山。
瀹茗澡尘虑，
褰帘饫孱颜。
精意孚海岳，
清声摇佩环。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_554','留别王嘉叟检正','喻良能','宋','四海望霖雨，
一人须股肱。
我本田家子，
蹉跎将暮龄。
相逢岂在早，
一见盖已倾。
谓我虽秃犀，
敝帚亦足称。
持献先簬箘，
长篇有明徵。
公乎傥践言，
庶为老亲荣。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_555','留别王嘉叟检正','喻良能','宋','初寮久已往，
今谁主文盟。
王公有嫡孙，
见者服且惊。
胸中九云梦，
笔端三折肱。
招致道山中，
掉头不肯应。
论事常山蛇，
持身玉壶冰。
平生谢先容，
要津真自登。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_556','留别直院莫子斋少卿','喻良能','宋','郁郁千丈松，
植根在崇冈。
清阴亘十亩，
直干凌穹苍。
好风一披拂，
声韵谐宫商。
古来成大厦，
此物宜栋梁。
不待岁月久，
共看柱明堂。
微木有石植，
枯崖饱风霜。
三百甲子馀，
围才拱把强。
大楹分难充，
一桷庶可当。
傥容附松末，
虽晚庸何伤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_557','蚊','喻良能','宋','慢肤秋来困扑缘，
手不胜拍身听旃。
昨夜狞飙惬人意，
一扫天宇何澄鲜。
蚊子蚊孙与蚋伯，
飞鸣适意须明年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_558','都丞李侍郎叔永和予小园二十六诗因成古风一首奉谢','喻良能','宋','黄昏兀坐对疏竹，
歘有寒光临蔀屋。
焚香发轴得新诗，
炯炯骊珠二十六。
三唐妙音久已断，
辋川丽藻今能续。
报瓜何必枉琼华，
抵鹊奚须费明玉。
韩豪苏仙吁可畏，
白俗元轻何足录。
从此磬湖三亩园，
绝胜李愿一盘谷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_559','都丞侍郎再和屋字韵诗次韵奉酬','喻良能','宋','小园五亩依篁竹，
中有茆茨数椽屋。
小桥度水既窈窕，
侧径穿花仍曲六。
惯看翠碧羽差池，
时听黄鹂声断续。
诗成持鼓过雷门，
谁信抛砖能引玉。
长篇丽句为藩饰，
小草么花蒙著录。
悬知家世以诗鸣，
压倒平泉与昌谷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_560','偶成','喻良能','宋','寓居东青城北端，
夏室阴阴簟色寒。
瓜盘那复集蝇蚋，
研沼似欲生波澜。
奇奇怪怪石几壑，
谡谡苍苍竹数竿。
枕扇衣斑自不恶，
时文思索愧空餐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_561','偶题','喻良能','宋','少陵五十六，
负暄候樵牧。
我今年与齐，
而亦处幽独。
小亭数椽净，
新月半钩曲。
聊将万斛愁，
付与一杯绿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_562','寄周彦礼知丞楼文举司理','喻良能','宋','从容里闬待时须，
二老风流孰与俱。
迁善节香如故否，
望云迎月更佳无。
醲寒凛凛侵衣袂，
薄雪斑斑入画图。
欲把一杯论旧事，
五年魂梦隔江湖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_563','寄湖口刘少魏主簿求皂湖石','喻良能','宋','平生爱石似奇章，
老矣一拳犹未致。
夜来梦绕太湖侧，
万玉嶙峋清有味。
梦回身复落红尘，
闻道皂湖山可人。
幸致一峰为我寿，
为君作诗传不朽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_564','望月台','喻良能','宋','滟滟冰轮林上头，
烟锁雾敛桂花浮。
要看夜静天如水，
莫遣疏帘不上钩。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_565','望所居西山瀑布','喻良能','宋','山居鲜欢悰，
理策事遨嬉。
嵚岑属初霁，
眺览得所宜。
悬崖有飞瀑，
注壑从凉飔。
濛濛喷雾雨，
冉冉含烟曦。
清泠讵可汰，
驶激畴能陂。
会心欣有得，
徙倚不知疲。
雁荡境千里，
香炉天一涯。
平生未能瞩，
昏旦矧欲窥。
何如兹山溜，
若与幽人期。
他年营菟裘，
舍是将安之。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_566','雪中赏横枝梅花','喻良能','宋','横枝梅花最先开，
影著清浅无纤埃。
寿阳妆额依然在，
姑射冰肌何处来。
无数雪花新点缀，
几番霜鬓独徘徊。
想见怀安官道侧，
十里洁白如琼瑰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_567','就报恩借碾碾茶彝老有诗因次其韵','喻良能','宋','断无鹅鸭恼比邻，
赖有钟鱼隔竹闻。
故遣新茶就佳硙，
要供戏䌽满瓯云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_568','悲夏畦','喻良能','宋','悲夏畦，
南亩苗未长，
东皋草已齐。
旋令妪妇办饷馌，
独引丁男耘稗稊。
悲夏畦，
炎天炙背如爇鸡，
渴来不得饮清溪。
宁知水榭冰山里，
犹自频嫌日未西。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_569','愧陶','喻良能','宋','渊明在彭泽，
到任八十日。
虽营三径资，
未穫公田秫。
珍重千金腰，
不为督邮折。
拂衣赋归来，
何异自投劾。
我生本樗散，
山林久蟠蛰。
虽非渊明俦，
颇亦慕幽迹。
偶然得一第，
遂窃升斗秩。
未书蓝田考，
已捧锦溪檄。
荒县饶逋负，
催科费鞭抶。
彊颜簿领间，
忽复弥数月。
心焉愧渊明，
俯首三叹息。
番江何时还，
哦松聊自适。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_570','温泉','喻良能','宋','招提閟林麓，
栋宇压江郊。
来作温泉浴，
如逢痒处搔。
䌽衣临砌槛，
华发对尊匏。
一笑凉风起，
红攲荔子梢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_571','游鹿田三洞','喻良能','宋','东西两鹿田，
上下三洞天。
苔径劣容足，
石门低及肩。
乳窦断还滴，
天窗皓仍玄。
何当出樊笼，
悠哉聊永年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_572','谢叶致政送芍药','喻良能','宋','佳葩如美人，
艳态妖且閒。
叶园美无度，
有花字雌丹。
晨妆谢膏沐，
秀色若可餐。
芳根裹春泥，
举赠不作难。
𦾏■照池亭，
一洗儒生酸。
从今杜陵眼，
不复嗟长寒。
何以报嘉惠，
作诗当琅玕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_573','谢君植矮梅百许株蟠屈如轮腊至皆著花洒洒可爱','喻良能','宋','孤竹低回首阳下，
许由偃蹇箕山巅。
谢君雅有林泉趣，
种得江梅如二贤。
南州腊月温和早，
赖有冰花除热恼。
鳞差百树夹径明，
似过山阴雪中道。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_574','辇下言怀','喻良能','宋','马蹄重踏帝京尘，
七载江湖饱问津。
白发有人疑甲子，
清斋无日不庚申。
不才讵敢诬明主，
厚禄那能羡故人。
乞得泮宫闽粤去，
未妨閒处著吾身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_575','道中口占','喻良能','宋','空山古寺里，
斋宿值冬晴。
尘嚣一何寂，
心境两俱清。
砌月晓霜色，
松风夜籁鸣。
语阑人未寝，
孤馆伴灯青。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_576','道中口占','喻良能','宋','出郭及初旭，
郊原豁寒晴。
云净空既碧，
霜明湖更清。
萧萧众木下，
杳杳孤鸿鸣。
安得陶谢手，
作诗替丹青。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_577','道旁松','喻良能','宋','郁郁千丈松，
谁栽荫脩路。
年祀寖绵邈，
斧斤时谬误。
皇华重怜恻，
霜根辱调护。
他日比甘棠，
流风继行露。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_578','新居成茂恭以诗见贺次韵奉酬','喻良能','宋','子美堂工始上元，
断手乃在宝应年。
顾我无能为杜役，
有此屋庐差不难。
欲移脩竹梅花亚，
暮霭朝烟迷上下。
室远地偏来者谁，
时有相思稽老驾。
平生愿足不愿馀，
底用虚名更著书。
虽无拄腹五千卷，
且有山阳宅一区。
海内长句君最好，
辱致新篇为善祷。
鸡豚社酒幸不远，
来往他年成二老。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_579','新浴','喻良能','宋','新浴换轻縠，
披襟临榧台。
好风知人意，
为我东南来。
晚池雨草青，
庶足充徘徊。
呼儿具绿樽，
聊进纳凉杯。
一酌暑气消，
再酌愁怀开。
三爵竟酩酊，
浩歌临苍苔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_580','遣兴','喻良能','宋','昔忝郡文学，
今为宗子师。
政怀三釜乐，
那复四愁诗。
时服光摇目，
香粳滑溜匙。
唯应讲风雅，
傥可解人颐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_581','豪士','喻良能','宋','东海一豪士，
西山两逸民。
涕唾弃周粟，
谈笑无秦军。
饿死骨仍香，
辞封名益芬。
至今千载下，
不敢轻隐沦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_582','潘淑妃','喻良能','宋','东昏当日宠容华，
潘妃步步生莲花。
阅武堂前种杨柳，
玉儿雪腕亲沽酒。
莲花不见杨柳空，
苍烟白露杂悲风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_583','题叶省干见示诗卷次韵一篇','喻良能','宋','微官讵足施才具，
每向閒中有佳句。
要同秦系下长城，
却笑屈原无圣处。
穿天出月摘清芬，
煎胶续弦唯有君。
命题探韵侪辈分，
昂昂野鹤在鸡群。
绿发才名今白首，
未数凭虚与乌有。
会当载酒擘鸾笺，
共试吟边三昧手。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_584','题红云岛','喻良能','宋','红云覆绝岛，
望之心神开。
弱水不负舟，
何由至蓬莱。
吾欲烦巨鳌，
为载三山来。
不然骑鲸去，
一醉流霞杯。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_585','题听雨轩','喻良能','宋','小轩在官舍，
不与嚣尘并。
清池浸窗槛，
修篁碍檐楹。
几当迢迢夜，
听此潇潇声。
怀哉对床约，
辗转难为情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_586','题张漕子温贵希斋','喻良能','宋','新营老先生，
喜好一何异。
端能友造物，
直欲骑元气。
古货今难卖，
太羹元少味。
阳春谁肯和，
玄白人争议。
知己如晨星，
一笑聊自慰。
先民不云乎，
有以少为贵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_587','题李氏拥万堂','喻良能','宋','我如王恭读书少，
君如邺侯藏书多。
排签插架三万轴，
知从何处能网罗。
上自先秦下五季，
奥帙隐篇皆略备。
不同邢邵懒校雠，
丹墨精研吁可贵。
君不见庐山先生子李子，
白石房中富文史。
胸蟠万卷笔如神，
事业文章俱两美。
又不见西蜀刘公少常伯，
平生醢芹嗜图籍。
倾赀尽写中秘书，
随身卷轴车连轭。
迩来置书事经纶，
论思献纳日日新。
君今堂中书汗牛，
愿君学李兼学刘。
尽揽英华归肺腑，
一鸣便作冲天举。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_588','题泛五湖游东山图','喻良能','宋','陶朱西子功名后，
安石东山隐遁初。
画图三挹春风面，
豁得平生俊气无。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_589','题径山一览亭','喻良能','宋','历览众峰顶，
下视飞鸟背。
一身凌紫霞，
迥出尘寰外。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_590','题圆通寺至乐亭次待制王公韵','喻良能','宋','地偏境自佳，
烟云绕孤屋。
寒声渺疏松，
翠影澹脩竹。
林深桂花晚，
微风度馀馥。
特用永岁年，
聊足媚幽独。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_591','题悯孝庙次王龟龄韵','喻良能','宋','曹娥卓行传丰碑，
越人往往贵女儿。
建炎蔡氏有孝子，
事比孝子尤瑰奇。
自从结发读书史，
倜傥不受靮与羁。
乃翁诖误落囹圄，
疚心疾首泣以悲。
胡能安坐视父系，
朝暮哀诉当旌麾。
府公傥许赎父罪，
名隶卒伍所不辞。
不然奋身事征讨，
赳赳勇力犹可施。
黄堂沈深身则微，
虽有诚恳无人知。
归来静默心语口，
此事感悟当以尸。
临河勇决不复顾，
纯孝宁不由天资。
缇萦上书解刑网，
言虽迫切身无亏。
文本理冤由一赋，
孰与捐命如含饴。
杀身成仁古所罕，
殆类饿踣齐与夷。
事闻黄屋亦动色，
亟诏立祠河水湄。
嗟嗟玄应固不朽，
万口至今皆一词。
东嘉夫子好事者，
作歌登载仍吁嘻。
异时国史编宋雅，
人间重见白华诗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_592','题旌忠庙次王龟龄韵','喻良能','宋','睢阳截然当贼中，
婴城既久粮食空。
矢死不降有二公，
青史皎皎书其忠。
国家涵养自建隆，
上至鹓鹭下罴熊。
一节一义皆获通，
无不昭然简宸衷。
建炎多难谁奋躬，
开门纳降何匆匆。
达官尚尔况困穷，
嗟嗟唐侯一何雄。
抽砖击敌甘命终，
愿以颈血污刃红。
精诚贯日亘云穹，
上彻九重达尧聪。
诏令血食居镇东，
激昂臣子忠勇风。
嘉名千古齐华崧，
王仙作诗美抗戎，
岂比尔雅诂鱼虫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_593','题晚节香亭','喻良能','宋','周侯人中英，
为文若翻水。
苦节凌雪霜，
香名馥兰芷。
考槃在幽谷，
篁竹富清美。
竹边两桂树，
碧叶光薿薿。
扁堂曰节香，
欲以规业履。
竹桂日以茂，
业履日以修。
一觞一咏知未称，
愿续离骚赋远游。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_594','题渊明祠堂','喻良能','宋','宅边虽有五柳树，
归去已荒三径园。
平生胸中羞五斗，
偶尔城市羡华轩。
盈樽浊酒自可漉，
得趣古琴那用弦。
欲知耿耿忠愤意，
甲子断自永初年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_595','题渊明醉石','喻良能','宋','平生忆渊明，
偶此访遗迹。
柴桑仅未泯，
栗里犹可识。
寒溜澹泠泠，
孤烟轻羃羃。
抚事良多感，
西风生醉石。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_596','题楞伽寺李公山房藏书阁','喻良能','宋','小阁峥嵘在空谷，
云是先生读书屋。
不见善和数千卷，
空闻邺侯三万轴。
先生一去几经年，
山色依然为谁绿。
只今赖有卫夫人，
壁上萧萧数竿竹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_597','磨勘转朝请郎','喻良能','宋','脱身畎亩簉簪绅，
父母妻孥均沐恩。
百年七万二千饭，
要须一饭不忘君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_598','赠神童林公滋公泽女神童幼玉','喻良能','宋','一英二孺同一家，
衮衮诵书几五车。
语音娅姹春帘燕，
稚齿清便兰砌芽。
联茵并载惊都市，
万里青云从此始。
两驹应佩金削刀，
双鬟会作女博士。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_599','书赵德庄词后','喻良能','宋','老眼看书成雾，
介庵墨妙金篦。
波底斜阳红湿，
绝胜彩笔新题。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_600','亦好园群花盛开戏成','喻良能','宋','小圃初乾晓雨，
杂花争试新妆。
揉色似观濯锦，
吹香如过河阳。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_601','亦好园群花盛开戏成','喻良能','宋','三岁无诸国里，
青春不是花时。
今日小园春半，
百般红紫芳菲。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_602','访何茂恭于南湖作三绝句','喻良能','宋','啼饥妻子眼底，
厚禄故人日边。
一钱不直谁念，
五十无闻自怜。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_603','访何茂恭于南湖作三绝句','喻良能','宋','十里相望烟树，
旬月不绝篮舆。
漱石枕流戏䌽，
浮家泛宅南湖。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_604','访何茂恭于南湖作三绝句','喻良能','宋','南湖绿发居士，
恰少磬湖八年。
掀雷抉电杰句，
出月穿天大篇。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_605','茂恭见和再用前韵奉酬','喻良能','宋','朗朗百间羊肸，
森森千丈长舆。
一身宜著台阁，
半生流落江湖。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_606','茂恭见和再用前韵奉酬','喻良能','宋','少陵时时醉里，
子山日日愁边。
白发新来满镜，
故人万一能怜。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_607','茂恭见和再用前韵奉酬','喻良能','宋','忆昔永新番水，
俱吏江左三年。
不作载苡马援，
聊为留犊苗篇。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_608','题李通判断桥图','喻良能','宋','桥上笋舆岌岌，
桥下浪波沄沄。
但觉往来无恼，
不知观者伤神。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_609','题李通判断桥图','喻良能','宋','平生心地夷坦，
一旦足跟崄巇。
不是篮舆安稳，
只应神物护持。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_610','磬湖居士得片石于斗坡山其长五尺其广一尺有咫耸拔孤秀缜密温润绝不类此间石疑自他山飞来因目之曰飞来石','喻良能','宋','六丁驱石日本，
堕落斗坡山中。
一片苍圭紫玉，
几回秋雨春风。
不假镌镵刻削，
自然巧妙嵌空。
居士置之朝爽，
是谓飞来小峰。',NULL,'','{"preface": "", "note": ""}','六言诗','hefengbao/jingmo-data3'),
('rd3_1_611','连理枝','喻良能','宋','紫荆斜倚磬湖隈，
并干连枝锦作堆。
犹记太虚坛上木，
舞风双影并徘徊。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_612','玉山道中','谢肃','元末明初','一年三过东津桥，
千仞碧峰寒玉标。
古木影随山轿落，
早梅香拂使旌飘。
群氓习俗敦昭代，
景佑神灵□□霄。
此去闽关悬鸟道，
长安虽远日非遥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_613','山中','喻峙','宋','我是山中万户侯，
明知骑马胜骑牛。
晚来马上看山色，
不似骑牛得自由。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_614','蜡梅香','喻陟','北宋','晓日初长，
正锦里轻阴，
小寒天气。
未报春消息，
早瘦梅先发，
浅苞纤蕊。
揾玉匀香，
天赋与，
风流标致。
问陇头人，
音容万里。
待凭谁寄。
一样晓妆新，
倚朱楼凝盼，
素英如坠。
映月临风处，
度几声羌管，
愁生乡思。
电转光阴，
须信道飘零容易。
且频欢赏，
柔芳正好，
满簪同醉。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_1_615','游虎丘','富严','宋','缭绕禅关锁翠微，
游人到此便忘归。
古今不尽春风恨，
一剑清泉浸落晖。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_616','游灵岩','富言','北宋','闻说灵岩境最幽，
乘閒舣棹共追游。
飞泉翠滴半空雨，
古树阴连万壑秋。
缥缈香烟笼梵榻，
嵯峨山势枕江流。
登临眺望关河远，
惹起乡思恋国愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_617','紫微山','富临','北宋','凿石诛茅四十年，
棱层宝构出诸天。
更逢地胜惊游客，
不负身披坏衲田。
别郡坐看云散后，
平湖下压鸟飞前。
还知老令忘归否，
为惜难移近县廛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_618','尧夫先生示秋霁登石阁之句病中聊以短章戏答','富弼','北宋','高阁岧峣对远山，
雨馀愁望不成欢。
拟将敛黛强消遣，
却是幽思苦未阑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_619','岁在癸丑年始七十正旦日书事','富弼','北宋','人生七十古来稀，
今日愚年已及期。
从此光阴犹不测，
只应天道始相知。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_620','岁在癸丑年始七十正旦日书事','富弼','北宋','先圣明明许纵心，
山川风月恣游寻。
此中若更论规矩，
籍外闲人不易禁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_621','岁在癸丑年始七十正旦日书事','富弼','北宋','亲宾何用举椒觞，
已觉闲中岁月长。
不学香山醉歌舞，
只将吟啸敌流光。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_622','岁在癸丑年始七十正旦日书事','富弼','北宋','今年始是乞骸年，
我向年前已挂冠。
都为君王怜久疾，
肯教先去养衰残。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_623','弼观罢走笔书后卷','富弼','北宋','黎民于变是尧时，
便字尧夫德可知。
更览新诗名击壤，
生生全道略无遗。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_624','弼窃览长篇断章有十二人中第二人之句又赋一绝上呈','富弼','北宋','顾我年龄虽第一，
在公勋德自无双。
不推行业终难敌，
富贵康宁亦可降。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_625','嵩巫亭','富弼','北宋','平地烟霄此半分，
绣楣丹槛照清汾。
风帘暮捲秋空碧，
剩见西山数岭云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_626','题范希文手书伯夷颂墨迹','富弼','北宋','夷清韩颂古皆无，
更得高平小楷书。
旧相嘉篇题卷后，
苏家能事复何如。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_627','十月二十四日早始见雪登白云台闲望乱道走书呈尧夫先生','富弼','北宋','气候随时应，
初寒雪已盈。
乾坤一色白，
山水万重清。
是处人烟合，
无穷鸟雀惊。
忻然不成下，
连把玉罍倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_628','台上再成乱道走书呈尧夫','富弼','北宋','密雪终宵下，
晨登百尺端。
瑞光翻怯日，
和气不成寒。
天末无织翳，
云头未少乾。
四郊闻击壤，
农望已多欢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_629','过邵尧夫先生','富弼','北宋','先生自卫客西畿，
乐道安閒绝世机。
再命初筵终不起，
独甘穷巷寂无依。
贯穿百代尝探古，
吟咏千篇亦造微。
珍重相知忽相访，
醉和风雨夜深归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_630','寄裴士林','富弼','北宋','渤澥宣和旅翮飞，
不堪朱邸负前期。
东城晓骑思行乐，
南浦春波怨别离。
对竹岂能忘旧主，
折麻方喜遇深知。
冕旒正注方臣重，
应许州人借一期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_631','弼承索近诗复贶佳句辄次元韵奉和诗以语志不必更及乎诗也伏惟一览而已','富弼','北宋','出入高车耀缙绅，
从来天幸喜逢辰。
道孤常恐难逃悔，
性拙徒能不失真。
风雨坐生无妄疾，
林泉归作自由身。
岁寒未必输松柏，
已见人间七十春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_632','答郑州祖龙图见寄原韵','富弼','北宋','坐拥双旌甫浚郊，
总戎曾未属鞬櫜。
千金寡妙方移疾，
二府交修敢惮劳。
处世机牙都不竞，
摄生权柄急须操。
他时病起君恩报，
始信林泉属我曹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_633','睢阳五老图','富弼','北宋','休官致政老年閒，
庙堂尝享著袍冠。
调和鼎鼐施霖雨，
燮理阴阳佐武桓。
念国不忘先世烈，
归乡岂念旧庐寒。
我辈若从亲炙授，
仪容如在使人看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_634','留守太尉相公就居为耆年之会承命赋诗','富弼','北宋','西洛古帝都，
衣冠走集地。
岂惟名利场，
骤为耆德会。
大尹吾旧相，
旷怀轻富贵。
日与退老游，
台阁并省寺。
予惭最衰老，
亦许预其次。
遂俗肖仪容，
烂然彤绘事。
闽峤访精华，
鲛绡布绝艺。
令复崇宴衎，
聊以示慈惠。
幽居近铜驼，
荒敝仍湫庳。
塞路移君庖，
盈车载春醴。
献酬互相趣，
欢处不知止。
商岭有四翁，
晋林惟七子。
较我集诸贤，
盛衰何远尔。
兹事实可矜，
传之足千祀。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_635','寄欧阳公','富弼','北宋','滁州太守文章公，
谪官来此称醉翁。
醉翁醉道不醉酒，
陶然岂有迁客容。
公年四十号翁早，
有德亦与耆年同。
意古直出茫昧始，
气豪一吐阊阖风。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_636','寄题醉翁亭','富弼','北宋','偏州地狭民事简，
醉翁自放山水中。
琅琊倚天色苍翠，
逊泉落石声玲珑。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_637','涵虚阁','富弼','北宋','画阁高连百雉城，
涵虚应不愧标名。
门前柳色兼旗色，
座上琴声杂佩声。
肯羡五湖归范蠡，
未饶三径隐渊明。
我来恰值初晴后，
山影波光分外清。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_638','弼承索近诗复贶佳句辄次元韵奉和诗以语志不必更及乎诗也伏惟一览而已','富弼','北宋','赋分萧条只自如，
生平常向官情疏。
亡功每叹孤明主，
得谢何妨作老夫。
官品尚叨三事贵，
世缘应信一毫无。
病来髀肉消几尽，
尤觉阴阳系惨舒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_1_639','定州阅古堂','富弼','北宋','朔方之兵，
劲于九土。
尤劲而要，
粤惟定武。
兵劲在驭，
用则罴虎。
失驭而劲，
骄不可举。
曰保曰贝，
闭壁连阻。
武爵新守，
束手就虏。
皇帝曰噫，
汝武曷取。
有敝必革，
以儒于抚。
公来帅定，
始以威怒。
有兵悍横，
一用于斧。
连营怛之，
胆栗腰伛。
既惧而教，
如餔如乳。
以刺以射，
以钲以鼓。
无一不若，
师师旅旅。
列城自刺，
靡不和附。
阴沴为梗，
降此大雨。
大河破泄，
在河之浒。
民被黜垫，
田入莽污。
流离荡析，
不得其所。
公戚曰吁，
予敢宁处。
乃大招来，
乃大保聚。
乃营帛粟，
寒衣饥茹。
民归而安，
水下孰禦。
强弱死生，
由公复虑。
曰义曰仁，
震肃春煦。
合和蒸天，
天顺以序。
公境独稔，
爰麦爰黍。
公俗独乐，
夫耕妇杼。
人虽曰康，
公亦奚豫。
谓此一方，
民与兵具。
务剧任重，
稽古其裕。
人皆谓公，
与古为伍。
公文化民，
公武禦侮。
何思古人，
公不自许。
遂择奇匠，
绘于堂宇。
列其行事，
指掌可数。
前有古人，
在我门户。
后有来者，
依我墙堵。
斯堂勿坏，
有堂有故。
堂之不存，
来者曷睹。
宏乎焕乎，
千载是矩。',NULL,'','{"preface": "天下十八道，惟河北最重。河北三十六州军，就其中又析大名府定州真定府高阳关为四路，惟定州最要。定为一路治所，实天下要重之最。知是州者，兼本路兵马都部署，居则治民，出则治兵，非夫文武才全，望倾于时者，不能安疆埸屏王室也。然自国初已来，专以武臣帅诸路。庆历七年，甘陵妖贼据城叛，河北妖党相摇以谋应，卒骄将愞，人心大震。天子悟，始议选儒臣帅四路，以督诸将。乃起知郓州资政殿学士给事中昌黎韩公帅真定，以遏乱萌。明年春，贼诛人安。既而夏大雨，河决商胡，东北入于海。河北灾，人复不宁，流徙失业者四出，咸不翅千里，僵殍满道。天子恤然，且虞他癚，遂以公帅定。定既要重天下，宿兵素多，属伤残之后，官民枵困，征赋逃无几而兵不少减。兵袭旧幸歉，益骄以悍。公夙夜裁整，以威以怀，兵之骄不从令者，脁其首恶，斩以徇，略为条教。馀怗怗就约，不敢玟于室。至有调发者，远而弥戢，如公亲临。已而招集逋亡，四流争还，如啼孩奔父母，惟恐其后。至则充然各得其欲，农无废陇，赋有馀粒，不旁诛横敛而上下足。堙漏补罅，一面完固。公既击瞗梗之兵，又育彫瘵之民，左行斧钺，右哺饮食，乱者毕治，亡者毕存。礼法政教，向之人所不得闻者，今渐濡酣饫，无不贯彻。自是边人革其耳目，新其肝肠，优为而乐从，故人易治而功成速也。又明年秋，天子图公之功，诏加大学士。公先尝表其志，幸终三年，不愿亟易也。至天子抑骑召而使即以授，姑遂公请，亦以慰斯人爱公之心也。公惕宠处官，虽无事未尝辄自豫，念兵与民之急，宜无过者。矧临要重之路，忧虞所系，凡是绘画，不可以无法。乃择取历代贤守良将总若干人行事，创大屋，以类相次，绘于周壁，谇之曰阅古堂。盖欲阅古之人所为而为之法也。噫！公雅文盓武，自当视乎古人。且天下方迟公入辅，以致太平，若其安疆埸屏王室，岂庸考古而后能哉？实公冲然，不自有其有，而归乎古人也。其悬知来者，不师绘事而公是师也。虽然，蹋古蒐善，惠人警己，公之意谓其至矣乎！公邮问索诗，因粗序所致之旨，以志其始而示于后。诗曰：", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_1_640','句','富弼','北宋','遗德被生民。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_1_641','府舍西轩作','刘概','宋','昔年曾作潇湘客，
憔悴东秦归未得。
西轩忽见好溪山，
如何尚有楚乡忆。
读书误人四十年，
有时醉把阑干拍。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_1_642','偈','富弼','北宋','执相诚非，
破相亦妄。
不执不破，
是名实相。',NULL,'','{"preface": "", "note": ""}','偈颂','hefengbao/jingmo-data3'),
('rd3_1_643','多丽 寿刘帅','富㩋','宋','淡云收晓来春满湘中。
柳如烟花枝如糁，
万红千翠织浓。
照帘旌微穿丽日，
动罗幕轻转香风。
天上良辰，
人间淑景，
生贤和气显殊钟。
映时表南山北斗，
相并两穹崇。
须知道英明罕比，
文武谁同。
奉慈亲承颜戏彩，
更闻吉梦占熊。
扫蛮氛遂清三楚，
定徐方行策元功。
趣召遄归，
康时佐主，
指挥谈笑虏巢空。
寿觞举器舟斟海，
不用水精钟。
休辞醉，
千龄会遇，
美事重重。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_1_644','句','强幼安','北宋','山僧不解数甲子，
一叶落知天下秋。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_1_645','九日有感二首','强至','北宋','忆昨方陪上相筵，
召书忽到菊杯前。
主人举酒勤令饮，
一醉秋风恰二年。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_646','九日有感二首','强至','北宋','每岁登高尽醉归，
未曾轻负菊花期。
今年枕上酬佳节，
感泪双痕落似丝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_647','九月十日龙兴寺饮饯蹇磻翁赴梁门酒半题名南轩因偶书屋壁','强至','北宋','昨日曾来把酒卮，
隔宵已过菊花期。
回头一笑成陈迹，
不独秋香有盛衰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_648','二月二十六日偶书','强至','北宋','旧年把酒对花频，
酒气花香日傍人。
今岁酒疏花未见，
惟将感泪湿青春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_649','又自和二首','强至','北宋','好把悲欢付一卮，
明朝北客有行期。
劝君莫听骊驹曲，
只恐催人两鬓衰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_650','又自和二首','强至','北宋','万事人间若漏卮，
喜情常满固难期。
却将昨日樽前菊，
零落金钿己觉衰。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_651','三月十日作','强至','北宋','一病十日不出门，
坐销芳意疏清樽。
今朝骑马探花去，
枝上十空无一存。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_652','上诗惠酒有谢','强至','北宋','登高无具结欢悰，
狂写愁吟叩主翁。
遽荷兵厨均美酿，
却将酩酊谢西风。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_653','马上见庭竹','强至','北宋','玉圆碧瘦与谁期，
只待丹山䌽凤饥。
生傍短墙真失所，
可怜直节众人窥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_654','书香山寺壁','强至','北宋','精蓝孤绝乱云间，
云外疑无路可还。
顾我尘喧非白傅，
缘何今日到香山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_1_655','公度惠花走笔戏谢','强至','北宋','二月都城未见花，
不知春色落谁家。
